    justify-content: center;
    padding: 0;
}

.memori-artifact-drawer--close .memori-icon-close,
.memori-artifact-drawer--close svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    fill: none;
    stroke: currentColor;
}

/* Content */
.memori-artifact-drawer--content {
    position: relative;
    display: flex;
    overflow: hidden;
    min-height: 0;
    flex: 1;
    padding: 0 0 1.5rem;
    gap: var(--memori-spacing-lg);
}

.memori-artifact-drawer--main {
    position: relative;
    display: flex;
    overflow: visible;
    min-width: 0;
    flex: 1;
    flex-direction: column;
    border: 1px solid rgba(255, 255, 255, 0.3);
    border-radius: var(--artifact-drawer-radius-lg);
    backdrop-filter: blur(20px);
    background: rgba(255, 255, 255, 0.6);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

.memori-artifact-drawer--main::before {
    position: absolute;
    top: 0;
    right: 0;
    left: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(0, 123, 255, 0.3), transparent);
    content: '';
}

.memori-button--more-options {
    padding: var(--memori-spacing-sm) var(--memori-spacing-md);
    border: 1px solid var(--memori-border-color, #e1e5e9);
    border-radius: var(--memori-radius-control);
}

.memori-artifact-toolbar--chatlog .memori-button--more-options {
    flex-shrink: 0;
}

@media (max-width: 768px) {
    .memori-artifact-toolbar--chatlog .memori-tab-switch__tab {
        position: relative;
        min-width: 2.25rem;
        padding: 0.35rem 0.5rem;
    }

    .memori-artifact-toolbar--chatlog .memori-tab-switch__label {
        position: absolute;
        overflow: hidden;
        width: 1px;
        height: 1px;
        padding: 0;
        border-width: 0;
        margin: -1px;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
    }

    .memori-artifact-toolbar--chatlog .memori-button--more-options {
        display: flex;
        width: 2.25rem;
        min-width: 2.25rem;
        height: 2.25rem;
        min-height: 2.25rem;
        align-items: center;
        justify-content: center;
        padding: 0;
    }
}

.memori-artifact-drawer--sidebar {
    width: 300px;
    flex-shrink: 0;
    padding: 1rem;
    padding-left: 1rem;
    border-radius: var(--memori-radius-surface);
    border-left: var(--memori-border) solid var(--memori-primary);
    background: var(--memori-primary-subtle);
}

.memori-widget .memori-artifact-drawer--close .memori-icon-close {
    width: 16px;
    height: 16px;
    fill: none;
    stroke: currentColor;
}

/* Mobile Drawer Panel */
.memori-artifact-drawer--panel-mobile {
    position: fixed;
    position: relative;
    z-index: 1001;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    overflow: hidden;
    width: 100%;
    height: 100vh;
    padding: 1rem 1.5rem 1.5rem;
    border-radius: 0;
    backdrop-filter: blur(20px);
    background: linear-gradient(135deg, var(--artifact-drawer-bg) 0%, rgba(248, 250, 252, 0.95) 100%);
    box-shadow: none;
    font-family: var(--memori-font-family);
}

.memori-artifact-toolbar .memori-artifact-actions {
    flex: 0 0 auto;
}

@media (max-width: 1024px) {
    .memori-artifact-drawer-fullscreen {
        display: none;
    }
}

/* Responsive Design */
@media (max-width: 1260px) {
    /* Hide the empty desktop-only action bar on mobile — all actions live in top-right */
    .memori-artifact-drawer-container-actions {
        display: none;
    }

    /* Mobile header: full-width toolbar — tabs left, more+close right */
    .memori-artifact-drawer-top-right {
        display: flex;
        overflow: visible;
        width: 100%;
        box-sizing: border-box;
        flex-shrink: 0;
        align-items: center;
        justify-content: space-between;
        padding: var(--memori-spacing-sm) var(--memori-spacing-md);
        border-bottom: 1px solid var(--memori-border-color);
        margin: 0;
        background: var(--memori-secondary-background);
        gap: var(--memori-spacing-sm);
    }

    .memori-artifact-drawer-top-right-actions {
        display: inline-flex;
        flex-shrink: 0;
        align-items: center;
        margin-left: auto;
        gap: var(--memori-spacing-sm);
    }

    .memori-artifact-drawer-top-right .memori-mobile-actions-menu {
        margin-left: 0;
    }

    /* Tabs.Root from @memori.ai/ui defaults to width:100% — that pushes actions off-screen */
    .memori-artifact-drawer-top-right .memori-tab-switch,
    .memori-artifact-drawer-top-right .memori-tabs {
        width: auto;
        max-width: fit-content;
        flex: 0 0 auto;
        justify-content: flex-start;
        /* border: var(--memori-border, 1px) solid color-mix(in srgb, var(--memori-text-color, #111827) 18%, transparent); */
    }

    .memori-artifact-drawer-top-right .memori-tab-switch__tab {
        min-width: 40px;
        flex: 0 0 auto;
    }

    /* Make mobile more-options match header toolbar buttons */
    .memori-artifact-drawer-top-right .memori-button--more-options {
        display: flex;
        width: 2.5rem;
        min-width: 2.5rem;
        height: 2.5rem;
        min-height: 2.5rem;
        align-items: center;
        justify-content: center;
        padding: 0;
        margin-left: 0;
    }

    /* Content fills remaining viewport under the toolbar (no floating card) */
    .memori-artifact-panel-drawer .memori-artifact-panel--content,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-panel--content {
        overflow: hidden;
        width: 100%;
        height: auto;
        min-height: 0;
        max-height: none;
        flex: 1 1 auto;
        gap: 0;
    }

    .memori-artifact-panel-drawer .memori-artifact-panel--main,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-panel--main {
        overflow: hidden;
        min-height: 0;
        flex: 1 1 auto;
    }

    .memori-artifact-panel-drawer .memori-artifact-preview,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-preview,
    .memori-artifact-panel-drawer .memori-artifact-preview-content,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-preview-content,
    .memori-artifact-panel-drawer .memori-artifact-tab-content--active,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-tab-content--active,
    .memori-artifact-panel-drawer .memori-artifact-content,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-content {
        border-radius: 0;
    }

    .memori-artifact-panel-drawer .memori-artifact-tab-content--active,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-tab-content--active {
        padding: 0;
    }

    .memori-artifact-panel-drawer .memori-artifact-preview-content,
    .memori-artifact-panel-drawer-fullscreen .memori-artifact-preview-content {
        background: transparent;
    }
}

@media (max-width: 1260px) {
    /* Mobile header actions */
    .memori-artifact-drawer-header-actions {
        display: none;
    }

    .memori-artifact-mobile-actions {
        position: absolute;
        z-index: 1001;
        top: 1rem;
        right: 1rem;
        display: block;
    }

    /* Mobile drawer styles */
    .memori-artifact-drawer--panel-mobile {
        position: fixed !important;
        top: 0 !important;
        right: 0 !important;
        bottom: 0 !important;
        left: 0 !important;
        width: 100% !important;
        max-width: 100% !important;
        height: 100vh !important;
        padding: 1rem 1.5rem 1.5rem;
        border-radius: 0 !important;
        backdrop-filter: blur(20px) !important;
        background: linear-gradient(135deg, var(--artifact-drawer-bg) 0%, rgba(248, 250, 252, 0.95) 100%) !important;
        box-shadow: none !important;
        transform: translateX(100%) !important;
    }

    .memori-artifact-drawer[data-headlessui-state~='open'] .memori-artifact-drawer--panel-mobile {
        transform: translateX(0) !important;
    }

    .memori-artifact-drawer--header {
        flex-direction: column;
        padding: 1.5rem;
        border-radius: 0;
        margin-bottom: 1rem;
        backdrop-filter: blur(20px) !important;
        background: linear-gradient(135deg, var(--memori-primary-subtle) 0%, rgba(255, 255, 255, 0.9) 100%) !important;
        gap: var(--memori-spacing-lg);
    }

    .memori-artifact-drawer--header-content {
        width: 100%;
    }

    .memori-artifact-drawer--header-actions {
        position: relative;
        position: absolute;
        top: 0px;
        right: 0px;
        right: 65px;
        width: 100%;
        max-width: 250px;
        justify-content: space-between;
        justify-content: flex-end;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        backdrop-filter: blur(10px) !important;
        background: rgba(255, 255, 255, 0.5) !important;
        opacity: 1;
        transform: none;
    }

    .memori-artifact-drawer--content {
        overflow: hidden;
        min-height: 0;
        flex: 1;
        flex-direction: column;
        padding: 0 0 1.5rem;
    }

    .memori-artifact-drawer--main {
        overflow: visible;
        min-height: 0;
        flex: 1;
        border: 1px solid rgba(255, 255, 255, 0.3) !important;
        border-radius: var(--artifact-drawer-radius-lg) !important;
        backdrop-filter: blur(20px) !important;
        background: rgba(255, 255, 255, 0.6) !important;
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1) !important;
    }

    .memori-artifact-drawer--meta {
        width: 100%;
        gap: var(--memori-spacing-sm);
    }

    .memori-artifact-drawer--meta-item {
        width: 100%;
        justify-content: center;
        font-size: 0.75rem;
    }

    /* Ensure full screen coverage */
    .memori-artifact-drawer--backdrop {
        backdrop-filter: blur(8px) saturate(180%) !important;
        background: linear-gradient(135deg, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0.3) 100%) !important;
    }
}

@media (min-width: 1261px) {
    /* Hide mobile drawer on desktop — inline column layout takes over */
    .memori-artifact-drawer {
        display: none !important;
    }

    /* Show web panel on desktop */
    .memori-artifact-panel {
        display: flex !important;
    }
}

/* Fullscreen Mode */
.memori-artifact-drawer--fullscreen .memori-artifact-drawer--panel {
    width: 100% !important;
    max-width: 100% !important;
    border-radius: 0 !important;
    margin: 0 !important;
    box-shadow: none !important;
}

.memori-artifact-drawer--fullscreen .memori-artifact-drawer--backdrop {
    backdrop-filter: none;
    background-color: transparent;
}

/* Mobile Mode */
.memori-artifact-drawer--mobile .memori-artifact-drawer--panel {
    position: fixed !important;
    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    left: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    height: 100vh !important;
    border-radius: 0 !important;
    margin: 0 !important;
}

.memori-artifact-drawer--mobile .memori-artifact-drawer--backdrop {
    background-color: rgba(0, 0, 0, 0.5) !important;
}

.memori-artifact-drawer-container-actions--no-preview {
    justify-content: flex-end;
}

.memori-artifact-drawer-container-actions--chatlog {
    padding: 0rem 1rem;
}

.memori-artifact-drawer-top-right--mobile {
    justify-content: space-between;
}

/* Top Right Header Section */
.memori-artifact-drawer-top-right {
    z-index: 1001;
    display: flex;
    align-items: center;
    gap: var(--memori-spacing-sm);
}

/* Mobile Actions Dropdown — portaled popup (not under .top-right) */
.memori-mobile-actions-menu {
    position: relative;
    display: inline-block;
}

.memori-mobile-actions-trigger {
    display: inline-block;
}

.memori-dropdown__popup.memori-mobile-dropdown,
.memori-mobile-dropdown {
    z-index: 1100;
    min-width: 200px;
    max-width: min(280px, calc(100vw - 1.5rem));
    padding: var(--memori-spacing-xs);
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    /* Soft contrast vs canvas — not pure white / not heavy fill */
    background: color-mix(in srgb, var(--memori-text-color) 6%, var(--memori-secondary-background)) !important;
    box-shadow: var(--memori-shadow-lg);
    color: var(--memori-text-color);
}

.memori-mobile-dropdown .memori-artifact-action-btn,
.memori-mobile-dropdown .memori-dropdown__item,
.memori-dropdown__popup.memori-mobile-dropdown .memori-dropdown__item {
    display: flex;
    width: 100%;
    min-height: 40px;
    align-items: center;
    justify-content: flex-start;
    padding: 0.5rem 0.75rem;
    border: 1px solid transparent;
    border-radius: var(--memori-radius-control);
    background: transparent;
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    gap: var(--memori-spacing-sm);
    text-align: left;
}

.memori-mobile-dropdown .memori-artifact-action-icon,
.memori-mobile-dropdown .memori-dropdown__item-icon,
.memori-mobile-dropdown .memori-dropdown__item-icon svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    color: inherit;
    fill: none !important;
    stroke: currentColor;
}

@media (max-width: 1260px) {
    .memori-artifact-panel--header {
        margin-bottom: var(--memori-spacing-sm);
    }

    .memori-dropdown__popup.memori-mobile-dropdown,
    .memori-mobile-dropdown {
        min-width: 180px;
        max-width: calc(100vw - 1.5rem);
    }
}

/* Focus and Accessibility */
.memori-artifact-drawer--panel:focus {
    outline: none;
}

.memori-artifact-drawer--panel:focus-visible {
    outline: 2px solid var(--memori-primary);
    outline-offset: 2px;
}
