    display: flex;
    max-width: 2rem;
    max-height: 2rem;
    align-items: center;
    justify-content: center;
    padding: 0.5rem;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 50%;
    background-color: transparent;
    cursor: pointer;
}

.memori-share-button--trigger svg {
    width: 100%;
    max-width: 1rem;
    height: 100%;
    max-height: 1rem;
}

.memori-share-button--trigger-menu-item {
    width: 100%;
    max-width: none;
    max-height: none;
    justify-content: flex-start;
}

.memori-share-button--dropdown-item-content {
    display: inline-flex;
    width: 100%;
    min-height: 1.25rem;
    align-items: center;
    cursor: pointer;
}

.memori-share-button--dropdown-menu {
    min-width: 15.5rem;
    max-width: 19rem;
    padding: 0.375rem;
}

.memori-share-button--dropdown-section {
    display: grid;
    gap: 0.125rem;
}

.memori-share-button--inline-list {
    display: flex;
    width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: 0;
}

.memori-share-button--inline-list .memori-share-button--dropdown-section {
    width: 100%;
    gap: 0.125rem;
}

.memori-share-button--inline-item {
    display: inline-flex;
    width: 100%;
    min-height: 2.75rem;
    align-items: center;
    justify-content: flex-start;
    padding: 0.7rem 0.75rem;
    border: 0;
    border-radius: var(--memori-radius-control);
    appearance: none;
    background: transparent;
    color: var(--memori-text-color, #111827);
    cursor: pointer;
    font: inherit;
    font-size: 1rem;
    font-weight: 500;
    gap: 0.7rem;
    line-height: 1.3;
    text-align: left;
    touch-action: manipulation;
}

.memori-share-button--inline-item svg {
    width: 1.125rem;
    max-width: 1.125rem;
    height: 1.125rem;
    max-height: 1.125rem;
    flex-shrink: 0;
}

.memori-share-button--inline-item > span {
    min-width: 0;
}

.memori-share-button--inline-item:disabled {
    cursor: not-allowed;
    opacity: 0.45;
}

.memori-share-button--inline-item:active:not(:disabled) {
    background-color: color-mix(in srgb, var(--memori-primary, #3b82f6) 12%, transparent);
}

@media (hover: hover) and (pointer: fine) {
    .memori-share-button--inline-item:hover {
        background-color: color-mix(in srgb, var(--memori-primary, #3b82f6) 10%, transparent);
    }
}

.memori-share-button--dropdown-divider {
    height: 1px;
    margin: 0.375rem 0.125rem;
    background-color: color-mix(in srgb, var(--memori-text-color, #111827) 12%, transparent);
}

/* All actionable menu rows: press feedback */
.memori-share-button--menu-item {
    position: relative;
    border-radius: var(--memori-radius-control);
    transition:
        background-color 0.2s ease,
        transform 0.12s ease;
}

.memori-share-button--menu-item:active:not(:disabled) {
    transform: scale(0.985);
}

/* Same primary tint as copy success, brief feedback on share / export / social / QR */
.memori-share-button--menu-item--flash {
    background-color: color-mix(in srgb, var(--memori-primary, #3b82f6) 12%, transparent);
}

.memori-share-button--copy-item--success {
    background-color: color-mix(in srgb, var(--memori-primary, #3b82f6) 12%, transparent);
}

.memori-share-button--copy-item--error {
    background-color: color-mix(in srgb, #ef4444 10%, transparent);
}

.memori-share-button--copy-icon {
    transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.memori-share-button--copy-item--success .memori-share-button--copy-icon {
    animation: memori-share-copy-check-pop 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) both;
    color: var(--memori-primary, #3b82f6);
}

.memori-share-button--copy-label {
    transition: opacity 0.15s ease;
}

.memori-share-button--copy-item--success .memori-share-button--copy-label {
    font-weight: 600;
}

.memori-share-button--copy-item--error .memori-share-button--copy-label {
    color: #b91c1c;
}

@keyframes memori-share-copy-check-pop {
    0% {
        opacity: 0.85;
        transform: scale(0.6) rotate(-12deg);
    }

    60% {
        transform: scale(1.08) rotate(4deg);
    }

    100% {
        opacity: 1;
        transform: scale(1) rotate(0deg);
    }
}

.memori-share-button--qr-download {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: var(--memori-radius-control);
    margin-top: 0.25rem;
    background: transparent;
    /* color: var(--memori-primary, #3b82f6); */
    cursor: pointer;
    font: inherit;
    /* font-weight: 600; */
    gap: 0.5rem;
    transition:
        background-color 0.2s ease,
        transform 0.12s ease;
}

.memori-share-button--qr-download svg {
    width: 1rem;
    max-width: 1rem;
    height: 1rem;
    max-height: 1rem;
    flex-shrink: 0;
}

.memori-share-button--qr-download:hover {
    background-color: color-mix(in srgb, var(--memori-primary, #3b82f6) 10%, transparent);
}

.memori-share-button--qr-download:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--memori-primary, #3b82f6) 55%, transparent);
    outline-offset: 2px;
}

.memori-share-button--qr-item {
    display: flex;
    justify-content: center;
    padding: 0.625rem;
}

.memori-share-button--qr-content {
    display: flex;
    width: 100%;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
}

.memori-share-button--qr-download:active {
    transform: scale(0.985);
}

@media (prefers-reduced-motion: reduce) {
    .memori-share-button--menu-item,
    .memori-share-button--copy-item,
    .memori-share-button--copy-icon,
    .memori-share-button--copy-label,
    .memori-share-button--qr-download {
        animation: none;
        transition: none;
    }

    .memori-share-button--menu-item:active:not(:disabled),
    .memori-share-button--qr-download:active {
        transform: none;
    }
}

.memori-share-button--overlay {
    position: absolute;
    right: auto;
    left: 0;
    display: flex;
    min-width: 14rem;
    flex-direction: column;
    padding: 0.5rem 0;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: var(--memori-radius-surface);
    margin: 0;
    margin-top: var(--memori-spacing-sm);
    background-color: #fff;
    box-shadow: 0 5px 10px rgba(0, 0, 0, 0.12);
    color: var(--memori-text-color);
    list-style: none;
    outline: none;
    transform-origin: top right;
}

.memori-share-button.memori-share-button--align-left .memori-share-button--overlay {
    right: 0;
    left: auto;
    transform-origin: top left;
}

li.memori-share-button--li {
    display: flex;
    align-items: center;
    justify-content: center;
}

button.memori-share-button--link,
a.memori-share-button--link {
    width: 100%;
    justify-content: flex-start;
    color: inherit;
    font-weight: normal;
    text-align: left;
    text-decoration: none;
}

.memori-share-button--li-qr-code {
    margin-top: var(--memori-spacing-sm);
    text-align: center;
}

.memori-share-button--li-qr-code button {
    background: #fff;
    color: var(--memori-text-color);
    cursor: pointer;
}

.memori-share-button--li-qr-code button:hover,
.memori-share-button--li-qr-code button:focus {
    background: #fff;
    color: var(--memori-text-color);
}

.memori-share-button--li-shared {
    padding-bottom: 0.25rem;
    border-bottom: 1px solid var(--memori-primary);
    margin-bottom: var(--memori-spacing-sm);
}

.memori-share-button--inline-list .memori-share-button--dropdown-section-social {
    display: grid;
    padding: 0.35rem 0 0.15rem;
    gap: 0.35rem;
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.memori-share-button--inline-list .memori-share-button--dropdown-section-social .memori-share-button--inline-item {
    min-height: 4.35rem;
    flex-direction: column;
    justify-content: center;
    padding: 0.65rem 0.35rem;
    font-size: 0.75rem;
    font-weight: 500;
    gap: 0.4rem;
    text-align: center;
}

.memori-share-button--inline-list
    .memori-share-button--dropdown-section-social
    .memori-share-button--inline-item
    > span {
    overflow: hidden;
    max-width: 100%;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-share-button--inline-list .memori-share-button--dropdown-divider {
    margin: 0.4rem 0.25rem;
}

.memori-share-button--inline-list .memori-share-button--qr-content {
    padding: 0.65rem 0.25rem 0.15rem;
}

.memori-share-button--inline-list .memori-share-button--qr-download {
    width: 100%;
    min-height: 2.5rem;
    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    font-weight: 500;
}
