    /* Same rhythm between messages whether or not the action row is rendered;
       with an addon this also keeps the translated row inside the hover hit area. */
    padding-bottom: calc(var(--memori-spacing-md) + var(--memori-spacing-xs));
}

.memori-chat--bubble-anchor:has(.memori-reasoning) {
    gap: 6px;
}

.memori-chat--bubble-anchor--from-user {
    align-items: flex-end;
}

/* Artifact chips sit in the shell under the bubble: drop the addon slot so
   copy/feedback does not float in a hole above the card. */
.memori-chat--bubble-shell:has(.memori-chat--artifact-block) .memori-chat--bubble-anchor {
    padding-bottom: 0;
}

.memori-chat--bubble-anchor--from-user .memori-chat--bubble-addon {
    right: 0;
    left: auto;
}

.memori-chat--artifact-block {
    width: fit-content;
    max-width: 100%;
    margin-bottom: 0;
}

.memori-chat--artifact-block--chatlog {
    max-width: 100%;
}

.memori-chat--artifact-block--chatlog.memori-chat--artifact-block--expanded {
    width: 100%;
}

.memori-chat--bubble-anchor--has-addon:focus-within .memori-chat--bubble-addon,
.memori-chat--bubble-container.memori-chat--addon-open .memori-chat--bubble-addon {
    opacity: 1;
    pointer-events: auto;
    transform: translate3d(0, -8px, 0) scale(1);
}

.memori-chat--bubble-container.memori-chat--with-addon .memori-chat--bubble {
    width: fit-content;
    min-width: 3.5rem;
    max-width: 100%;
}

.memori-chat--bubble-anchor--has-addon:focus-within .memori-chat--bubble,
.memori-chat--bubble-container.memori-chat--addon-open .memori-chat--bubble {
    box-shadow: var(--memori-chat-addon-elevation);
}

/* Wide markdown code blocks and tables scroll inside the bubble instead of
   stretching the conversation column. */
.memori-chat--bubble-container.memori-chat--with-addon .memori-chat--bubble:has(pre, table, .memori-chat--code-block) {
    min-width: 0;
}

@media (hover: hover) and (pointer: fine) {
    .memori-chat--bubble-anchor--has-addon:hover .memori-chat--bubble-addon {
        opacity: 1;
        pointer-events: auto;
        transform: translate3d(0, -8px, 0) scale(1);
    }
}

.memori-chat--bubble-container.memori-chat--addon-open .memori-chat--bubble.memori-chat--user-bubble {
    box-shadow: var(--memori-chat-addon-elevation);
}

@media (hover: hover) and (pointer: fine) {
    .memori-chat--bubble-anchor--has-addon:hover .memori-chat--bubble {
        box-shadow: var(--memori-chat-addon-elevation);
    }

    .memori-chat--bubble-anchor--has-addon:hover .memori-chat--bubble.memori-chat--user-bubble {
        box-shadow: var(--memori-chat-addon-elevation);
    }
}

.memori-chat--bubble-addon-tooltip-trigger {
    display: inline-flex;
    flex-shrink: 0;
}

/* Portal to widget surface so tooltip anchoring is not thrown off by the addon transform.
   Keep the library tooltip z-index scale (base + 1300) so the tooltip stays above the
   website assistant box, which sits at base + 1000 with a non-zero --memori-z-index-base.
   Hide during enter/exit so the popup never flashes at 0,0 (top of the page) when
   Floating UI hasn't applied coordinates yet, or when the trigger loses focus. */
.memori-chat--bubble-addon-tooltip-positioner {
    z-index: calc(var(--memori-z-index-base, 0) + 1300);
}

.memori-chat--bubble-addon-tooltip-positioner[data-starting-style],
.memori-chat--bubble-addon-tooltip-positioner[data-ending-style] {
    opacity: 0 !important;
    pointer-events: none;
    visibility: hidden;
}

.memori-chat--bubble-ai-icon {
    display: inline-flex;
    width: 1.75rem;
    height: 1.75rem;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    color: var(--memori-text-color);
    cursor: pointer;
    pointer-events: auto;
}

/* stylelint-disable-next-line no-descending-specificity -- icon size scoped after action-icon rules */
.memori-chat--bubble-ai-icon svg {
    width: 1rem;
    height: 1rem;
}

.memori-chat--bubble-addon button {
    flex-shrink: 0;
    transition: all 0.3s ease-in-out;
}

/* ShareButton copy affordances on circular bubble actions (see ShareButton.css) */
.memori-chat--bubble-addon button.memori-chat--bubble-action-button.memori-share-button--copy-item--success:hover {
    background-color: color-mix(in srgb, var(--memori-primary, #3b82f6) 12%, transparent);
}

.memori-chat--bubble-addon button.memori-chat--bubble-action-button.memori-share-button--copy-item--error:hover {
    background-color: color-mix(in srgb, #ef4444 10%, transparent);
}

.memori-chat--bubble-addon button.memori-share-button--copy-item--error .memori-share-button--copy-icon {
    color: #b91c1c;
}

.memori-chat--bubble-action-button:hover {
    background-color: var(--memori-secondary-background) !important;
}

.memori-chat--bubble-addon button.memori-chat--bubble-action-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.memori-chat--bubble-addon button.memori-chat--bubble-action-button .memori-button__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    line-height: 0;
}

.memori-chat--bubble-addon button.memori-chat--bubble-action-button--sources {
    width: auto;
    min-width: 1.875rem;
    height: 1.875rem;
    align-items: center;
    padding: 0 0.75rem;
    border-radius: var(--memori-radius-xs);
    background: color-mix(in oklch, var(--memori-primary) 12%, transparent);
    color: var(--memori-primary);
    font-size: var(--memori-text-size-xs);
    font-weight: var(--memori-text-weight-medium);
    gap: 6px;
    line-height: 1;
}

.memori-chat--bubble-addon button.memori-chat--bubble-action-button--sources-empty {
    background: transparent;
    color: color-mix(in oklch, var(--memori-text-color) 55%, transparent);
}
.memori-chat--bubble .memori-chat--bubble-action-icon {
    display: flex;
    justify-content: flex-end;
    padding: calc(var(--memori-spacing-xs) / 2);
    text-align: right;
}

.memori-chat--bubble .memori-chat--bubble-action-icon svg {
    overflow: visible;
    width: 1rem;
    height: 1rem;
    color: var(--memori-text-color);
}

.memori-chat--bubble .memori-chat--bubble-action-icon.memori-chat--bubble-action-icon--copied {
    border-color: var(--memori-primary) !important;
    background-color: rgba(76, 111, 255, 0.08);
}

.memori-chat--bubble .memori-chat--bubble-action-icon.memori-chat--bubble-action-icon--copied svg {
    color: var(--memori-primary, #4c6fff);
}

.memori-chat--bubble .memori-chat--bubble-action-icon.memori-chat--bubble-action-icon--ai {
    padding: calc(var(--memori-spacing-xs) * 0.75);
}

.memori-chat--bubble .memori-chat--bubble-action-icon.memori-chat--bubble-action-icon--debug {
    color: var(--memori-error);
}

.memori-chat--bubble .memori-chat--bubble-action-icon.memori-chat--bubble-action-icon--debug svg {
    color: currentColor;
}

.memori-chat--bubble-addon .memori-chat--feedback {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    padding: 0;
    margin: 0;
}

.memori-chat--bubble-addon .memori-chat--feedback button {
    width: auto;
    min-width: 0;
    height: auto;
    min-height: 0;
    padding: 0;
    padding: var(--memori-spacing-sm);
    border: 0;
    border-radius: var(--memori-radius-xs);
    color: var(--memori-text-color);
}

.memori-chat--bubble .memori-chat--bubble-action-icon.memori-chat--bubble-action-icon--ai svg {
    width: 0.85rem;
    height: 0.85rem;
}

.memori-chat--bubble-addon button.memori-chat--bubble-action-icon {
    padding: calc(var(--memori-spacing-xs) / 2);
    border-radius: var(--memori-radius-xs);
}

.memori-chat--bubble-action-feedback {
    margin-left: var(--memori-spacing-xs);
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-semibold);
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.memori-chat--bubble-action-feedback--from-user {
    color: var(--memori-primary-content);
}

.memori-chat--bubble-addon .memori-chat--feedback button .memori-button--icon svg {
    width: 0.9rem;
    height: 0.9rem;
}

.memori-chat--bubble-addon-separator {
    width: 1px;
    height: 1.5em;
    margin: 0 0.5em;
    background: #ccc;
}

.memori-chat--bubble-addon .memori-tooltip {
    display: inline-flex;
    align-items: center;
}

.memori-chat--bubble-addon .memori-tooltip .memori-tooltip--trigger {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    line-height: 0;
    text-align: center;
}

.transition {
    transition-property: all;
}

.ease-in-out {
    transition-timing-function: ease-in-out;
}

.duration-300 {
    transition-duration: 300ms;
}

.scale-075 {
    transform: scale(0.75);
}

.scale-1 {
    transform: scale(1);
}

.opacity-0 {
    opacity: 0;
}

.opacity-1 {
    opacity: 1;
}

.translate-x-15 {
    transform: translateX(15px);
}

.translate-x--15 {
    transform: translateX(-15px);
}

.translate-x-30 {
    transform: translateX(30px);
}

.translate-x--30 {
    transform: translateX(-30px);
}

.translate-x-0 {
    transform: translateX(0);
}

.memori-chat--bubble-content {
    width: 100%;
    font-weight: 400;
}

.memori-chat--user-bubble .memori-chat--bubble-content,
.memori-chat--user-bubble .memori-chat--bubble-content p,
.memori-chat--user-bubble .memori-chat--bubble-content div,
.memori-chat--user-bubble .memori-expandable {
    font-size: var(--memori-text-size-sm);
    font-weight: 400;
    line-height: 1.5;
}

.memori-chat--bubble output {
    display: none;
}

.dot mjx-container[jax='CHTML'][display='true'] {
    text-align: left;
}

.memori-chat--user-bubble
    .memori-expandable--collapsed
    .memori-expandable__inner
    > .memori-chat--bubble-content::after {
    content: '…';
}

.memori-chat--function-cache-modal.memori-modal__viewport .memori-modal__popup,
.memori-chat--function-cache-modal .memori-modal--panel {
    height: 100%;
    max-height: 80vh;
    border-radius: var(--memori-radius-overlay);
    background-color: var(--memori-main-background, #fff);
    overflow-y: auto;
}

.memori-chat--function-cache-toolbar {
    display: flex;
    margin-bottom: var(--memori-spacing-md);
}

.memori-chat--function-cache-entries {
    display: flex;
    flex-direction: column;
    gap: var(--memori-spacing-lg);
}

.memori-chat--function-cache-entry {
    padding-top: var(--memori-spacing-md);
    border-top: var(--memori-border) solid var(--memori-border-color);
}

.memori-chat--function-cache-entry:first-child {
    padding-top: 0;
    border-top: none;
}

.memori-chat--function-cache-entry-title {
    margin: 0 0 var(--memori-spacing-sm);
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-md);
    font-weight: var(--memori-text-weight-semibold);
    line-height: var(--memori-text-line-tight);
}

.memori-chat--function-cache-entry-pre {
    max-width: 100%;
    box-sizing: border-box;
    padding: var(--memori-spacing-md);
    border: var(--memori-border) solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    margin: 0;
    background: color-mix(in oklch, var(--memori-text-color) 4%, var(--memori-secondary-background));
    color: var(--memori-text-color);
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace;
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-normal, 1.5);
    overflow-wrap: anywhere;
    overflow-x: auto;
    white-space: pre-wrap;
    word-break: break-word;
}

details.memori-think {
    display: block;
    width: 100%;
    max-width: 100%;
    margin-bottom: var(--memori-spacing-sm);
    background: transparent;
    font-size: 13px;
    font-style: normal;
    line-height: 1.65;
}

details.memori-think summary {
    display: list-item;
    color: color-mix(in oklch, var(--memori-text-color) 52%, transparent);
    cursor: pointer;
    font-weight: 500;
    list-style: none;
}

details.memori-think summary::-webkit-details-marker {
    display: none;
}

details.memori-think summary:hover {
    color: color-mix(in oklch, var(--memori-text-color) 82%, transparent);
}

details.memori-think[open] {
    color: color-mix(in oklch, var(--memori-text-color) 62%, transparent);
}

details.memori-think[open] summary {
    margin-bottom: var(--memori-spacing-xs);
    color: color-mix(in oklch, var(--memori-text-color) 52%, transparent);
}
