___CSS_LOADER_EXPORT___.push([module.id, `/**
 * ArtifactHandler CSS Styles
 * Following the project's design system and CSS patterns
 */

/* Align width with ChatBubble when rendered in chat (same container + max-width) */
.memori-artifact-handler-spacer {
    width: 40px;
    min-width: 40px;
    flex-shrink: 0;
    margin-right: var(--memori-spacing-sm);
}

button.memori-artifact-handler {
    width: auto;
    max-width: 100%;
    color: inherit;
    font: inherit;
    text-align: left;
}

.memori-artifact-handler {
    --memori-artifact-chevron-rest: -90deg;

    display: flex;
    min-width: 0;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    /* border: var(--memori-border) solid var(--memori-border-color); */
    border: none;
    border-radius: var(--memori-radius-surface);
    animation: fadeInUp 0.5s ease forwards;
    backdrop-filter: blur(4px);
    background: var(--memori-main-background);
    cursor: pointer;
    gap: 8px;
    opacity: 0;
    transform: translateY(10px);
    transition:
        border-color 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.memori-artifact-handler-wrapper {
    width: 100%;
}

.memori-artifact-handler-wrapper > .memori-artifact-handler {
    width: 100%;
    max-width: 100%;
}

.memori-artifact-handler--active {
    border-color: var(--memori-primary);
    background: linear-gradient(135deg, var(--memori-primary) 0%, #764ba2 100%);
    box-shadow: 0 4px 16px rgba(130, 70, 175, 0.3);
    color: var(--memori-primary-content);
}

.memori-artifact-handler--active:hover {
    box-shadow: 0 6px 20px rgba(130, 70, 175, 0.4);
    transform: translateY(-2px);
}

.memori-artifact-handler-content {
    display: flex;
    align-items: center;
    padding: var(--memori-spacing-lg);
    gap: var(--memori-spacing-sm);
}

.memori-artifact-handler-icon {
    flex-shrink: 0;
    font-size: 1.25rem;
    line-height: 1;
}

.memori-artifact-handler-icon svg {
    display: block;
    width: 1em;
    height: 1em;
}

.memori-artifact-handler-toggle svg {
    width: 16px;
    height: 16px;
    stroke-width: 2;
}

/* Black SVG glyphs → white when widget is in dark theme (see styles.css [data-theme='dark']) */
[data-theme='dark'] .memori-artifact-handler-icon svg {
    filter: brightness(0) invert(1);
}

.memori-artifact-handler-info {
    min-width: 0;
    flex: 1;
}

.memori-artifact-handler-action-icon {
    width: 24px;
    height: 24px;
    flex-shrink: 0;
    font-size: var(--memori-text-size-2xl);
    line-height: 1;
}

/*
 * One ChevronDown. Rest angle points at where the panel opens;
 * aria-expanded adds 180° so open always reverses that direction.
 *   bottom (chatlog accordion): down → up
 *   side (layout column / overlay): right → left
 */
.memori-artifact-handler[data-placement='bottom'] {
    --memori-artifact-chevron-rest: 0deg;
}

.memori-artifact-handler-chevron {
    transform: rotate(var(--memori-artifact-chevron-rest));
    transform-origin: center;
    transition: transform var(--memori-motion-duration-fast, 0.15s) var(--memori-motion-ease-out, ease);
}

.memori-artifact-handler[aria-expanded='true'] .memori-artifact-handler-chevron {
    transform: rotate(calc(var(--memori-artifact-chevron-rest) + 180deg));
}

@media (prefers-reduced-motion: reduce) {
    .memori-artifact-handler-chevron {
        transition: none;
    }
}

.memori-artifact-handler-title {
    overflow: hidden;
    margin-bottom: var(--memori-spacing-xs);
    color: inherit;
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-semibold);
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-artifact-handler-subtitle {
    overflow: hidden;
    margin-bottom: var(--memori-spacing-xs);
    color: inherit;
    font-size: 0.75rem;
    opacity: 0.7;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-artifact-handler-meta {
    display: flex;
    flex-wrap: wrap;
    font-size: 0.625rem;
    gap: var(--memori-spacing-sm);
    opacity: 0.6;
}

.memori-artifact-handler-type {
    padding: 0.125rem 0.375rem;
    border-radius: var(--memori-radius-control);
    background: rgba(0, 0, 0, 0.1);
    color: inherit;
    font-weight: var(--memori-text-weight-medium);
    letter-spacing: 0.025em;
    text-transform: uppercase;
}

.memori-artifact-handler-custom-title {
    overflow: hidden;
    max-width: 120px;
    padding: 0.125rem 0.375rem;
    border-radius: var(--memori-radius-control);
    background: rgba(0, 0, 0, 0.1);
    color: inherit;
    font-style: italic;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-artifact-handler--active .memori-artifact-handler-type,
.memori-artifact-handler--active .memori-artifact-handler-custom-title {
    background: rgba(255, 255, 255, 0.2);
}

.memori-artifact-handler-actions {
    flex-shrink: 0;
}

.memori-artifact-handler-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0.375rem;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: var(--memori-radius-control);
    background: rgba(0, 0, 0, 0.05);
    color: inherit;
    cursor: pointer;
    transition: all 0.2s ease;
}

.memori-artifact-handler-toggle:hover {
    background: rgba(0, 0, 0, 0.1);
    transform: scale(1.05);
}

.memori-artifact-handler--active .memori-artifact-handler-toggle {
    border-color: rgba(255, 255, 255, 0.3);
    background: rgba(255, 255, 255, 0.2);
}

.memori-artifact-handler-toggle:focus {
    outline: 2px solid var(--memori-primary);
    outline-offset: 2px;
}

.memori-artifact-handler-toggle:focus:not(:focus-visible) {
    outline: none;
}

.memori-artifact-handler--active .memori-artifact-handler-toggle:hover {
    background: rgba(255, 255, 255, 0.3);
}

/* Animation */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Responsive Design */
@media (max-width: 768px) {
    .memori-artifact-handler {
        min-width: 0;
        margin: 0;
    }

    .memori-artifact-handler-content {
        padding: 0.75rem;
        gap: var(--memori-spacing-sm);
    }

    .memori-artifact-handler-icon {
        font-size: var(--memori-text-size-xl);
    }

    .memori-artifact-handler-title {
        font-size: 0.8125rem;
    }

    .memori-artifact-handler-subtitle {
        font-size: 0.6875rem;
    }

    .memori-artifact-handler-meta {
        font-size: 0.5625rem;
    }

    .memori-artifact-handler-custom-title {
        max-width: 80px;
    }
}

/* Dark Mode Support */
@media (prefers-color-scheme: dark) {
    .memori-artifact-handler {
        /* background: rgba(26, 26, 26, 0.95); */
        border-color: var(--memori-border-color);
    }

    .memori-artifact-handler-type,
    .memori-artifact-handler-custom-title {
        background: rgba(255, 255, 255, 0.1);
    }

    .memori-artifact-handler-toggle {
        border-color: rgba(255, 255, 255, 0.1);
        background: rgba(255, 255, 255, 0.05);
    }

    .memori-artifact-handler-toggle:hover {
        background: rgba(255, 255, 255, 0.1);
    }
}

/* Focus States for Accessibility */
.memori-artifact-handler:focus {
    outline: 2px solid var(--memori-primary);
    outline-offset: 2px;
}

.memori-artifact-handler:focus:not(:focus-visible) {
    outline: none;
}
