___CSS_LOADER_EXPORT___.push([module.id, `/* Age verification uses Modal stacking="stacked"; keep backdrop tint only. */
.memori-modal__backdrop.age-verification-modal-backdrop {
    background: color-mix(in srgb, #000 45%, transparent);
}

.age-verification-modal,
.age-verification-modal * {
    box-sizing: border-box;
}

.age-verification-form {
    display: flex;
    width: 100%;
    flex-direction: column;
    align-items: center;
}
/* 
@media (min-width: 640px) {
    .age-verification-form {
        min-width: 600px;
    }
} */

.age-verification-form fieldset,
.age-verification-form .age-verification-birth-field {
    padding-right: 0;
    padding-left: 0;
    border: 0;
}

.age-verification-form .form-item,
.age-verification-form .age-verification-birth-field {
    width: 100%;
    text-align: center;
}

.age-verification-form .memori-field__control-wrapper {
    width: 100%;
}

.age-verification-form .memori-field__description {
    padding-bottom: var(--memori-spacing-xs);
    margin: var(--memori-spacing-lg) 0 var(--memori-spacing-md);
    opacity: 0.5;
    text-align: left;
}

.age-verification-form .memori-field__error {
    padding-bottom: 0.25rem;
    margin: 1.5rem 0 1rem;
    color: var(--memori-error);
}

.age-verification-form .form-item.submit {
    margin-top: var(--memori-spacing-lg);
    text-align: center;
}

.age-verification-form .form-item input {
    color: var(--memori-text-color);
}

.age-verification-form .form-item-help {
    padding-bottom: var(--memori-spacing-xs);
    margin: var(--memori-spacing-lg) 0 var(--memori-spacing-md);
    opacity: 0.5;
    text-align: left;
}

.age-verification-form .form-item-error {
    padding-bottom: 0.25rem;
    margin: 1.5rem 0 1rem;
    color: var(--memori-error);
}

button.age-verification-submit {
    position: relative;
    overflow: hidden;
    width: 100%;
    min-width: 220px;
    max-width: 220px;
    min-height: 42px;
    padding: 1rem 2rem;
    border: none;
    border-radius: var(--memori-radius-control);
    margin-top: 1rem;
    background: var(--memori-primary);
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: var(--memori-text-size-md);
    font-weight: var(--memori-text-weight-semibold);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

button.age-verification-submit::before {
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    content: '';
    transition: left 0.5s ease;
}

button.age-verification-submit:hover::before {
    left: 100%;
}

button.age-verification-submit:active {
    transform: translateY(0);
}

.age-verification-text {
    margin-top: 0;
    margin-bottom: var(--memori-spacing-lg);
}
