    display: flex;
    align-items: center;
    gap: var(--memori-spacing-sm);
}

.memori-chat-history-drawer--search {
    display: flex;
    min-width: 0;
    flex: 1 1 auto;
    align-items: center;
}

.memori-chat-history-drawer--count {
    color: color-mix(in oklch, var(--memori-text-color) 64%, transparent);
    font-size: var(--memori-text-size-sm);
    white-space: nowrap;
}

.memori-chat-history-drawer--filters-toggle {
    min-height: 36px;
    align-self: flex-start;
    padding-right: var(--memori-spacing-sm);
    padding-left: var(--memori-spacing-sm);
    color: color-mix(in oklch, var(--memori-text-color) 72%, transparent);
}

.memori-chat-history-drawer--filters-toggle-label {
    display: inline-flex;
    align-items: center;
    gap: var(--memori-spacing-xs);
