    flex: 1 1 auto;
    flex-direction: column;
    gap: var(--memori-spacing-md);
}

.memori-chat-history-drawer--group {
    display: flex;
    flex-direction: column;
    gap: var(--memori-spacing-sm);
}

.memori-chat-history-drawer--group-label {
    margin: 0;
    color: color-mix(in oklch, var(--memori-text-color) 62%, transparent);
    font-size: var(--memori-text-size-xs);
    font-weight: var(--memori-text-weight-semibold);
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.memori-chat-history-drawer--list {
    display: flex;
    flex-direction: column;
    padding: 0;
    margin: 0;
    gap: var(--memori-spacing-sm);
    list-style: none;
}

.memori-chat-history-drawer--list-item {
    display: flex;
    align-items: center;
    padding: 2px;
    border: var(--memori-border) solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-secondary-background);
    gap: 2px;
}

.memori-chat-history-drawer--list-item-main {
    display: flex;
    min-width: 0;
    flex: 1 1 auto;
    align-items: center;
    padding: calc(var(--memori-spacing-md) - 2px) var(--memori-spacing-sm) calc(var(--memori-spacing-md) - 2px)
        var(--memori-spacing-md);
    border: 0;
    appearance: none;
    background: transparent;
    color: inherit;
    cursor: pointer;
    font: inherit;
    gap: var(--memori-spacing-sm);
    text-align: left;
}

.memori-chat-history-drawer--list-item:hover {
    background: var(--memori-main-background);
}

.memori-chat-history-drawer--list-item-main:focus-visible {
    border-radius: calc(var(--memori-radius-surface) - 2px);
    outline: 2px solid var(--memori-primary);
    outline-offset: 0;
}

.memori-chat-history-drawer--list-item--content {
    display: flex;
    min-width: 0;
    flex: 1 1 auto;
    flex-direction: column;
    gap: 3px;
}

.memori-chat-history-drawer--list-item--title {
    display: -webkit-box;
    overflow: hidden;
    min-width: 0;
    -webkit-box-orient: vertical;
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    -webkit-line-clamp: 2;
    line-height: var(--memori-text-line-tight);
    overflow-wrap: anywhere;
}

.memori-chat-history-drawer--list-item--meta {
    overflow: hidden;
    color: color-mix(in oklch, var(--memori-text-color) 64%, transparent);
    font-size: var(--memori-text-size-xs);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-chat-history-drawer--list-item-download.memori-button {
    flex-shrink: 0;
}

.memori-chat-history-drawer--list-item-chevron {
    width: 1.1rem;
    height: 1.1rem;
    flex-shrink: 0;
    margin-right: var(--memori-spacing-sm);
    color: color-mix(in oklch, var(--memori-text-color) 45%, transparent);
    pointer-events: none;
}

.memori-chat-history-drawer--list-item--disabled,
.memori-chat-history-drawer--list-item--disabled .memori-chat-history-drawer--list-item-main {
    cursor: not-allowed;
    opacity: 0.55;
}

.memori-chat-history-drawer--loading {
    display: flex;
    min-height: 12rem;
    flex: 1;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: color-mix(in oklch, var(--memori-text-color) 64%, transparent);
    gap: var(--memori-spacing-md);
}

/* Spin's icon is an absolute overlay, so a childless spinner collapses and the label sits on it. */
.memori-chat-history-drawer--loading .memori-spin {
    width: auto;
    height: auto;
}

.memori-chat-history-drawer--loading .memori-spin__overlay {
    position: static;
    width: auto;
    height: auto;
    opacity: 1;
}

.memori-chat-history-drawer--loading p {
    margin: 0;
}

.memori-chat-history-drawer--error {
    color: var(--memori-error);
}

.memori-chat-history-drawer--resume-cta {
    width: 100%;
    min-height: 44px;
}

.memori-chat-history-drawer--detail .memori-side-drawer__body {
    padding: 0;
    /* background: var(--memori-main-background); */
}

@media (max-width: 768px) {
    .memori-chat-history-drawer--toolbar-row {
        flex-wrap: wrap;
    }

    .memori-chat-history-drawer--search {
        flex-basis: 100%;
    }
}
