.memori--deep-thought-disclaimer__icon--compact {
    width: 1rem;
    height: 1rem;
    border: 1.5px solid var(--memori-info);
    background: color-mix(in oklch, var(--memori-info) 18%, transparent);
    color: var(--memori-info);
}

.memori--deep-thought-disclaimer__icon--compact span {
    font-size: 0.625rem;
    font-weight: var(--memori-text-weight-medium);
    line-height: 1;
}

.memori--deep-thought-disclaimer__icon svg {
    width: 1.125rem;
    height: 1.125rem;
}

.memori--deep-thought-disclaimer__muted {
    margin: 0.125rem 0 0;
    color: var(--memori-text-color);
    font-size: 0.75rem;
    line-height: var(--memori-text-line-relaxed);
    opacity: 0.72;
}

.memori--deep-thought-disclaimer__learn-more {
    margin: 0.375rem 0 0;
}

.memori--deep-thought-disclaimer__notice-card {
    display: flex;
    width: 100%;
    align-items: flex-start;
    justify-content: space-between;
    padding: 0.625rem 0.75rem;
    border: 1px solid color-mix(in oklch, var(--memori-border-color) 80%, white);
    border-radius: var(--memori-radius-surface);
    margin-top: var(--memori-spacing-xs);
    gap: var(--memori-spacing-sm);
}

.memori--deep-thought-disclaimer__notice-content {
    min-width: 0;
    flex: 1;
}

.memori--deep-thought-disclaimer__notice-title {
    margin: 0 0 0.125rem;
    color: var(--memori-text-color);
    font-size: 0.875rem;
    font-weight: var(--memori-text-weight-medium);
    line-height: var(--memori-text-line-relaxed);
}

.memori--deep-thought-disclaimer__notice-action {
    align-self: center;
    white-space: nowrap;
}

.memori--deep-thought-disclaimer__link {
    height: auto;
    min-height: 0;
    padding: 0;
    border: none;
    background: transparent;
    color: var(--memori-info);
    cursor: pointer;
    font-size: 0.75rem;
    font-weight: var(--memori-text-weight-medium);
    text-decoration: underline;
}

.memori--deep-thought-disclaimer__link:hover {
    opacity: 0.9;
}

.memori--deep-thought-disclaimer__learn-more-inline {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--memori-spacing-xs);
}

@media (max-width: 870px) {
    .memori--deep-thought-disclaimer__notice-card {
        flex-direction: column;
        align-items: stretch;
    }

    .memori--deep-thought-disclaimer__notice-action {
        align-self: flex-end;
    }
}

.memori--deep-thought-disclaimer__helper-toggle {
    display: inline-flex;
    min-width: 1.75rem;
    min-height: 1.75rem;
    align-items: center;
    justify-content: center;
    border: 1px solid color-mix(in oklch, var(--memori-info) 50%, var(--memori-border-color));
    border-radius: 999px;
    background: color-mix(in oklch, var(--memori-info) 8%, var(--memori-main-background));
    color: var(--memori-text-color);
}

.memori--deep-thought-disclaimer__helper-mobile {
    display: block;
    width: 100%;
    padding: var(--memori-spacing-sm);
    border-radius: var(--memori-radius-tooltip);
    margin-top: var(--memori-spacing-xs);
    background: var(--memori-tooltip-background);
    color: var(--memori-tooltip-foreground);
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-normal);
}

.memori--deep-thought-helper-tooltip-popup p {
    margin: 0;
}

.memori--deep-thought-disclaimer__body {
    min-width: 0;
    flex: 1;
}

.memori--deep-thought-disclaimer__body > p {
    margin: 0 0 var(--memori-spacing-sm);
}

.memori--deep-thought-disclaimer__body > p:last-child {
    margin-bottom: 0;
}

.memori--deep-thought-disclaimer__title-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--memori-spacing-sm);
}

.memori--deep-thought-disclaimer h3 {
    margin: 0;
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-md);
    font-weight: var(--memori-text-weight-semibold);
    line-height: var(--memori-text-line-relaxed);
    overflow-wrap: anywhere;
}

.memori--deep-thought-disclaimer__actions {
    margin-top: var(--memori-spacing-xs);
}

.memori--deep-thought-disclaimer .memori-tooltip {
    position: relative;
    flex-shrink: 0;
    margin: 0;
}

.memori--deep-thought-disclaimer .memori-tooltip .memori-tooltip--trigger svg {
    width: var(--memori-text-size-2xl);
    height: var(--memori-text-size-2xl);
    padding: var(--memori-spacing-xs);
    border: 1px solid color-mix(in oklch, var(--memori-info) 50%, var(--memori-border-color));
    border-radius: 50%;
    background: color-mix(in oklch, var(--memori-info) 8%, var(--memori-main-background));
    color: var(--memori-text-color);
}

.memori--deep-thought-disclaimer a {
    color: inherit;
    text-decoration: underline;
}

.memori--privacy-popover-trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: none;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.memori--privacy-popover-trigger:focus-visible {
    outline: var(--memori-focus-ring);
    outline-offset: var(--memori-focus-ring-offset);
}

/* Portal on widget root; tooltip/popover library z-index is base + 1300
   (base is 10000 in the website assistant, whose box sits at base + 1000).
   Hide while Floating UI is still applying coordinates so click-open
   never flashes at viewport 0,0 (same pattern as ChatBubble addon tooltips). */
.memori--privacy-popover-positioner,
.memori--deep-thought-helper-tooltip-positioner {
    z-index: calc(var(--memori-z-index-base, 0) + 1300);
}

.memori--privacy-popover-positioner[data-starting-style],
.memori--privacy-popover-positioner[data-ending-style],
.memori--deep-thought-helper-tooltip-positioner[data-starting-style],
.memori--deep-thought-helper-tooltip-positioner[data-ending-style] {
    opacity: 0 !important;
    pointer-events: none;
    visibility: hidden;
}

.memori--privacy-popover-popup {
    overflow: visible;
    max-width: min(20rem, calc(100vw - 2 * var(--memori-spacing-md)));
    box-sizing: border-box;
    padding: var(--memori-spacing-sm) var(--memori-spacing-md);
    border-radius: var(--memori-radius-tooltip);
    background: var(--memori-tooltip-background);
    box-shadow: var(--memori-shadow-lg);
    color: var(--memori-tooltip-foreground);
    font-size: var(--memori-text-size-sm);
    hyphens: auto;
    line-height: var(--memori-text-line-normal);
    overflow-wrap: anywhere;
}

/* Scroll the body, not the popup. The caret is a sibling that hangs
   outside the popup (bottom: -0.375rem), so overflow on the popup clips it. */
.memori--privacy-popover-popup .memori-tooltip__surface {
    max-height: min(50vh, 18rem);
    -webkit-overflow-scrolling: touch;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 55%, transparent) transparent;
    scrollbar-width: thin;
    touch-action: pan-y;
}

.memori--privacy-popover-popup .memori-tooltip__surface::-webkit-scrollbar {
    width: 8px;
}

.memori--privacy-popover-popup .memori-tooltip__surface::-webkit-scrollbar-track {
    background: transparent;
}

.memori--privacy-popover-popup .memori-tooltip__surface::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 45%, transparent);
}

.memori--privacy-popover-popup .memori-tooltip__surface::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 60%, transparent);
}

.memori--privacy-popover-content {
    text-align: left;
}

.memori--privacy-popover-content-list {
    padding-left: var(--memori-spacing-md);
}

/* Close button is absolutely positioned; keep the title out from under it. */
.memori--start-panel-info-modal.memori-modal__viewport .memori-modal__title,
.memori--start-panel-info-modal-title {
    min-width: 0;
    max-width: 100%;
    padding-right: calc(var(--memori-icon-button-size, 44px) + var(--memori-spacing-md));
    overflow-wrap: anywhere;
    white-space: normal;
    word-break: break-word;
}

@media (max-width: 480px) {
    .memori--settings-section__description {
        display: none;
    }

    .memori--cover {
        display: none;
    }
}
