        padding: 0.375rem 0.5rem;
        font-size: 0.65rem;
        line-height: var(--memori-text-line-tight);
    }

    .memori-media-item-preview--text {
        font-size: 0.8rem;
    }

    .memori-media-item-preview--text pre {
        padding: 0.75rem;
    }

    .memori-media-item-preview--content {
        min-height: 40vh;
        max-height: 50vh;
    }

    /* Mobile snippet improvements */
    .memori-media-item--snippet-direct {
        margin-bottom: var(--memori-spacing-lg);
    }

    .memori-media-item--snippet-direct .memori-snippet pre {
        padding: 0.75rem;
        font-size: 0.8rem;
    }

    .memori-media-item--snippet-direct .memori-snippet--copy-button {
        top: 0.5rem;
        right: 0.5rem;
        width: 28px !important;
        height: 28px !important;
    }

    .memori-media-item--snippet-direct .memori-snippet--copy-button svg {
        width: 12px;
        height: 12px;
    }

    .memori-media-item-preview--content .memori-snippet pre {
        padding: 1rem;
        font-size: 0.8rem;
    }
}

/* ============================================
   DOCUMENTS (Claude-style: filename, icon, meta)
   ============================================ */
a.memori-media-item--document-link {
    display: block;
    width: 100%;
    color: inherit;
    text-decoration: none;
}

.memori-media-item--document {
    position: relative;
    display: flex;
    width: 100%;
    min-height: 100px;
    flex-direction: column;
    padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-secondary-background);
    cursor: pointer;
    transition: box-shadow 0.2s ease;
}

.memori-media-item--document:hover {
    border: 1px solid var(--memori-primary);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.memori-media-item--document-header {
    display: flex;
    align-items: flex-start;
    gap: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
}

.memori-media-item--document-icon {
    display: flex;
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border-radius: var(--memori-radius-surface);
    background: #f3f4f6;
    color: var(--memori-text-color);
}

.memori-media-item--document-icon-svg {
    width: 20px;
    height: 20px;
    color: var(--memori-text-color);
}

.memori-media-item--document-title {
    display: -webkit-box;
    overflow: hidden;
    flex: 1;
    margin: 0;
    -webkit-box-orient: vertical;
    color: var(--memori-text-color);
    direction: ltr;
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    -webkit-line-clamp: 3;
    overflow-wrap: break-word;
}

.memori-media-item--document-badge {
    position: absolute;
    right: 12px;
    bottom: 12px;
    padding: var(--memori-spacing-xs) var(--memori-spacing-sm);
    border-radius: var(--memori-radius-surface);
    background: #f3f4f6;
    color: #000;
    font-size: 11px;
    font-weight: var(--memori-text-weight-semibold);
    letter-spacing: 0.02em;
    text-transform: uppercase;
}

/* Document tiles in grid: fill the reserved 120px cell */
.memori-media-items--grid .memori-media-item--document-link {
    display: block;
    width: 100%;
    height: 100%;
}

.memori-media-items--grid .memori-media-item--document {
    width: 100%;
    min-width: 0;
    max-width: none;
    height: 100%;
    min-height: 120px;
    box-sizing: border-box;
    background-color: var(--memori-secondary-background);
}

/* Tab focus — focus is on the link wrapper, not the inner card/document */
a.memori-media-item--link:focus-visible .memori-media-item--document,
div.memori-media-item--link:focus-visible .memori-media-item--document {
    border-color: var(--memori-border-primary, var(--memori-primary));
}

/* ============================================
   VIDEOS (MP4, QuickTime, AVI, MPEG)
   ============================================ */
.memori-media-item--video-container {
    position: relative;
    overflow: hidden;
    width: 100%;
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: #000;
    cursor: pointer;
    transition: box-shadow 0.2s ease;
}

.memori-media-item--video-container:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.memori-media-item--video-player {
    display: block;
    width: 100%;
    height: auto;
    min-height: 120px;
    max-height: 400px;
    border-radius: var(--memori-radius-surface);
}

.memori-media-item--video-overlay {
    position: absolute;
    z-index: 1;
    top: 50%;
    left: 50%;
    display: flex;
    width: 64px;
    height: 64px;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.6);
    pointer-events: none;
    transform: translate(-50%, -50%);
    transition: opacity 0.2s ease;
}

.memori-media-item--video-container:hover .memori-media-item--video-overlay {
    opacity: 0.8;
}

.memori-media-item--video-overlay.hidden {
    display: none;
}

.memori-media-item--play-icon {
    width: 32px;
    height: 32px;
    color: var(--memori-text-color);
}

/* ============================================
   AUDIO (MP3, WAV, MPEG)
   ============================================ */
.memori-media-item--audio-container {
    display: flex;
    width: 100%;
    min-height: 120px;
    box-sizing: border-box;
    align-items: center;
    padding: var(--memori-spacing-md);
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-main-background);
    gap: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    transition: box-shadow 0.2s ease;
}

.memori-media-item--audio-container:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.memori-media-item--audio-icon {
    display: flex;
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #3b82f6;
}

.memori-media-item--audio-player {
    min-width: 0;
    height: 32px;
    flex: 1;
}

.memori-media-item--audio-player::-webkit-media-controls-panel {
    background: transparent;
}

/* ============================================
   3D MODELS (GLTF)
   ============================================ */
.memori-media-item--model-container {
    position: relative;
    overflow: hidden;
    width: 100%;
    height: 400px;
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    cursor: grab;
    transition: box-shadow 0.2s ease;
}

.memori-media-item--model-container:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.memori-media-item--model-container:active {
    cursor: grabbing;
}

.memori-media-item--model-viewer {
    width: 100%;
    height: 100%;
}

.memori-media-item--model-controls {
    position: absolute;
    z-index: 10;
    right: 12px;
    bottom: 12px;
    display: flex;
    gap: var(--memori-spacing-sm);
}

.memori-media-item--model-control-btn {
    display: flex;
    width: 32px;
    height: 32px;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: var(--memori-radius-surface);
    background: rgba(0, 0, 0, 0.6);
    color: var(--memori-text-color);
    cursor: pointer;
    transition: background 0.2s ease;
}

.memori-media-item--model-control-btn:hover {
    background: rgba(0, 0, 0, 0.8);
}

/* ============================================
   CODE SNIPPETS (Inline and Block)
   ============================================ */
.memori-media-item--code-snippet-inline {
    display: flex;
    width: 100%;
    align-items: flex-start;
    padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs)) var(--memori-spacing-md);
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-main-background);
    font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
    font-size: 13px;
    gap: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    transition: box-shadow 0.2s ease;
}

.memori-media-item--code-snippet-inline:hover {
    box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.memori-media-item--code-language-badge {
    flex-shrink: 0;
    padding: calc(var(--memori-spacing-xs) / 2) var(--memori-spacing-sm);
    border-radius: var(--memori-radius-surface);
    background: #3b82f6;
    color: var(--memori-text-color);
    font-size: 11px;
    font-weight: var(--memori-text-weight-medium);
    line-height: var(--memori-text-line-normal);
    text-transform: uppercase;
}

.memori-media-item--code-content {
    flex: 1;
    margin: 0;
    color: var(--memori-text-color);
    line-height: var(--memori-text-line-normal);
    overflow-x: auto;
}

.memori-media-item--code-snippet-block {
    position: relative;
    overflow: hidden;
    width: 100%;
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: #1e1e1e;
    transition: box-shadow 0.2s ease;
}

.memori-media-item--code-snippet-block:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.memori-media-item--code-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--memori-spacing-sm) calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    border-bottom: 1px solid #3e3e3e;
    background: #2d2d2d;
}

.memori-media-item--code-language {
    margin: 0;
    color: var(--memori-text-color);
    font-size: 12px;
    font-weight: var(--memori-text-weight-medium);
    text-transform: uppercase;
}

.memori-media-item--code-actions {
    display: flex;
    gap: var(--memori-spacing-sm);
}

.memori-media-item--code-action-btn {
    padding: var(--memori-spacing-xs) var(--memori-spacing-sm);
    border: 1px solid #4b5563;
    border-radius: var(--memori-radius-surface);
    background: transparent;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: 11px;
    transition: all 0.2s ease;
}

.memori-media-item--code-action-btn:hover {
    border-color: #6b7280;
    background: #374151;
    color: var(--memori-text-color);
}

.memori-media-item--code-body {
    max-height: 400px;
    padding: var(--memori-spacing-md);
    overflow-x: auto;
    overflow-y: auto;
}

/* Syntax highlighting colors (Prism-like) */
.memori-media-item--code-body .token.comment {
    color: #6a9955;
}

.memori-media-item--code-body .token.string {
    color: #ce9178;
}

.memori-media-item--code-body .token.keyword {
    color: #569cd6;
}

.memori-media-item--code-body .token.function {
    color: #dcdcaa;
}

.memori-media-item--code-body .token.number {
    color: #b5cea8;
}

.memori-media-item--code-body .token.operator {
    color: var(--memori-text-color);
}

/* ============================================
   HTML PREVIEW
   ============================================ */
.memori-media-item--html-preview {
    overflow: auto;
    width: 100%;
    min-height: 200px;
    max-height: 600px;
    padding: var(--memori-spacing-md);
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-secondary-background);
    cursor: pointer;
    transition: box-shadow 0.2s ease;
}

.memori-media-item--html-preview:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.memori-media-item--html-preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: var(--memori-spacing-sm);
    border-bottom: 1px solid var(--memori-border-color);
    margin-bottom: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
}

.memori-media-item--html-preview-title {
    margin: 0;
    color: var(--memori-text-color);
    font-size: 12px;
    font-weight: var(--memori-text-weight-medium);
    text-transform: uppercase;
}

.memori-media-item--html-preview-content {
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    line-height: 1.6;
}

/* ============================================
   GENERIC FILES (Fallback)
   ============================================ */
.memori-media-item--generic-file {
    display: flex;
    width: 100%;
    align-items: center;
    padding: var(--memori-spacing-md);
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-main-background);
    cursor: pointer;
    gap: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    transition:
        box-shadow 0.2s ease,
        transform 0.2s ease;
}

.memori-media-item--generic-file:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.memori-media-item--generic-file:active {
    transform: scale(0.98);
}

.memori-media-item--generic-file-icon {
    display: flex;
    width: 48px;
    height: 48px;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border-radius: var(--memori-radius-surface);
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.memori-media-item--generic-file-info {
    min-width: 0;
    flex: 1;
}

.memori-media-item--generic-file-name {
    overflow: hidden;
    margin: 0;
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-media-item--generic-file-meta {
    margin: 0;
    margin-top: var(--memori-spacing-xs);
    color: var(--memori-text-color);
    font-size: 12px;
}

.memori-media-item--generic-file-action {
    flex-shrink: 0;
    padding: calc(var(--memori-spacing-xs) + 2px) calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: var(--memori-secondary-background);
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: 12px;
    transition: background 0.2s ease;
}

.memori-media-item--generic-file-action:hover {
    background: var(--memori-main-background);
}

/* ============================================
   GRID LAYOUTS FOR MIXED MEDIA
   ============================================ */
/* Documents, audio, and generic files stack vertically */
.memori-media-items--grid.list-items {
    max-width: 600px;
    grid-template-columns: 1fr;
}

/* Videos and 3D models can use 1-2 column layout */
.memori-media-items--grid.large-media {
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
}

/* Code snippets can be mixed width */
.memori-media-items--grid.code-snippets {
    max-width: 800px;
    grid-template-columns: 1fr;
}

/* Responsive adjustments for mixed media */
@media (max-width: 640px) {
    .memori-media-items--grid.large-media {
        grid-template-columns: 1fr !important;
    }

    .memori-media-item--model-container {
        height: 300px;
    }

    .memori-media-item--video-player {
        max-height: 300px;
    }
}

/* ============================================
   DARK FILE CARDS (Files: TXT, HTML, PDF, DOC, etc.)
   ============================================ */
.memori-media-item--card-file {
    position: relative;
    display: flex;
    min-height: 120px;
    flex-direction: column;
    padding: var(--memori-spacing-md);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: var(--memori-radius-surface);
    background: #363636;
    transition:
        box-shadow 0.2s ease,
        transform 0.2s ease;
}

.memori-media-item--card-file:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
    cursor: pointer;
}

.memori-media-item--card-file:active {
    transform: scale(0.98);
}

.memori-media-item--file-content {
    position: relative;
    display: flex;
    height: 100%;
    flex-direction: column;
}

.memori-media-item--file-title {
    overflow: hidden;
    flex: 1;
    margin-bottom: var(--memori-spacing-sm);
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    line-height: 1.4;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-media-item--file-meta {
    margin-bottom: auto;
    color: var(--memori-text-color);
    font-size: 12px;
    line-height: var(--memori-text-line-normal);
}

.memori-media-item--file-badge {
    position: absolute;
    bottom: 12px;
    left: 12px;
    padding: var(--memori-spacing-xs) var(--memori-spacing-sm);
    border-radius: var(--memori-radius-surface);
    background: rgba(255, 255, 255, 0.2);
    color: var(--memori-text-color);
    font-size: 11px;
    font-weight: var(--memori-text-weight-medium);
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

/* Link preview card styles */
.memori-media-item--card-cover-icon {
    display: flex;
    min-height: 120px;
    align-items: center;
    justify-content: center;
    padding: 2rem;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.memori-media-item--card-cover-img {
    display: block;
    width: 100%;
    height: auto;
    max-height: 300px;
    object-fit: cover;
    object-position: center;
}

/* Responsive for file cards */
@media (max-width: 640px) {
    .memori-media-item--card-file {
        min-height: 100px;
        padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
