width: 120px;\n    height: 120px;\n    min-height: 120px;\n    box-sizing: border-box;\n    padding: 0;\n}\n\n.memori-media-item--link .memori-media-item--image > div {\n    height: 100%;\n}\n\n/* User media: keep chronological order; avoid direction:rtl (Safari scroll bugs) */\n.memori-media-items--grid.memori-media-items--user {\n    max-width: 90%;\n    justify-content: end;\n    margin-block: 0;\n    margin-inline-end: 0;\n    margin-inline-start: auto;\n}\n\n/* Agent media: start-aligned */\n.memori-media-items--grid.memori-media-items--agent {\n    justify-content: start;\n    margin-block: 0;\n    margin-inline: 0;\n}\n\n.memori-media-item--card {\n    border: 1px solid var(--memori-border-color);\n    border-radius: var(--memori-radius-surface);\n    margin-bottom: 0;\n    background: transparent;\n    box-shadow: none;\n    transition: box-shadow 0.2s ease;\n}\n\n.memori-media-item--card:hover {\n    /* box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1); */\n    background: transparent;\n    cursor: pointer;\n    transform: none;\n}\n\n.memori-media-item--image .memori-card--content {\n    display: none;\n    padding: 0;\n}\n\n.memori-media-item--image .memori-card {\n    overflow: hidden;\n    width: 100%;\n    height: 100%;\n    border: 1px solid var(--memori-border-color);\n    border-radius: var(--memori-radius-surface);\n    margin: 0;\n    background: var(--memori-main-background);\n    box-shadow: none;\n}\n\n.memori-media-item .memori-card--cover {\n    height: auto;\n    border-radius: 0;\n    background: transparent;\n}\n\n.memori-media-item .memori-card--cover audio,\n.memori-media-item .memori-card--cover video {\n    border-radius: var(--memori-radius-surface);\n}\n\n.memori-media-item--image .memori-card--cover {\n    overflow: hidden;\n    height: 100%;\n    padding: 0;\n    border: none;\n    border-radius: 0;\n    margin: 0;\n    background: transparent;\n}\n\n.memori-media-item--figure {\n    display: flex;\n    overflow: hidden;\n    width: 10