    padding: 0.5rem;
    /* border-bottom: 1px solid var(--memori-border-color); */
    border-radius: var(--memori-radius-surface) var(--memori-radius-surface) 0 0;
    background: var(--memori-primary-subtle);
    gap: var(--memori-spacing-xs);
}

.memori-artifact-tab-icon {
    width: 16px;
    height: 16px;
}

.memori-artifact-tab {
    display: flex;
    align-items: center;
    padding: 0.75rem 1rem;
    border: none;
    border-radius: var(--memori-radius-surface);
    background: transparent;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    gap: var(--memori-spacing-sm);
    transition: all 0.2s ease;
    white-space: nowrap;
}

.memori-artifact-tab--active,
.memori-artifact-tab:hover,
.memori-artifact-tab:active,
.memori-artifact-tab:focus {
    background: var(--memori-main-background);
    box-shadow: var(--memori-shadow-sm);
    color: var(--memori-primary);
}

/* Content */
.memori-artifact-content {
    display: flex;
    overflow: visible;
    min-height: 0;
    flex: 1;
    flex-direction: column;
    border-radius: 0 0 var(--memori-radius-surface) var(--memori-radius-surface);
}

.memori-artifact-tab-content {
    display: none;
    overflow: hidden;
    min-height: 0;
    flex: 1;
}

.memori-artifact-tab-content--active {
    display: flex;
    overflow: hidden;
    min-height: 0;
    flex: 1 1 auto;
    flex-direction: column;
    padding: var(--memori-spacing-md);
}

/* Code Content */
.memori-artifact-code {
    flex: 1;
    border-radius: var(--memori-radius-surface);
    background: var(--memori-main-background);
    overflow-x: hidden;
    overflow-y: auto;
    /* border: 1px solid var(--memori-border-color); */
    /* margin: 1rem; */
}

.memori-artifact-code-content {
    padding: 1rem;
    margin: 0;
    color: var(--memori-text-color);
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Consolas', monospace;
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-normal);
    overflow-wrap: break-word;
    white-space: pre-wrap;
    word-wrap: break-word;
}

/* Preview Content */
.memori-artifact-preview-content {
    position: relative;
    display: flex;
    overflow: hidden;
    min-height: 0;
    flex: 1;
    flex-direction: column;
    border-radius: var(--memori-radius-surface);
    background: transparent;
}

.memori-artifact-preview-iframe {
    overflow: auto;
    width: 100%;
    height: 100%;
    min-height: 0;
    flex: 1;
    border: none;
    border-radius: var(--memori-radius-surface);
}

