   MEMORI REACT – FOGLIO DI STILE GLOBALE
   ========================================================================== */
/* Layer order matches @memori.ai/ui: theme < components < host overrides */
@layer memori.theme, memori.components, memori.overrides;

/* --- 1. Design system esterno (variabili, reset, token) ---
   NOTE: the bundler-style specifier below is intentional for dev/Storybook.
   Published \`dist/styles.css\` and \`esm/styles.css\` are bundled by PostCSS
   (\`postcss-import\`) so this import is inlined before publishing. */

/* --- 2. Stili per componente (ordine: componenti UI, poi layout) --- */

/* --- 3. Risorse esterne: font e KaTeX (formule matematiche) --- */

/* --- 4. Utility: testo visibile solo agli screen reader (accessibilità) --- */
.sr-only {
    position: absolute;
    overflow: hidden;
    width: 1px;
    height: 1px;
    padding: 0;
    border-width: 0;
    margin: -1px;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
}
.memori.memori-widget.memori-layout-chat,
.memori.memori-widget.memori-layout-fullpage,
.memori.memori-widget.memori-layout-zoomed_full_body {
    /* Portal root for Floating UI menus — do NOT set contain here.
       Use 100dvh (not height:100% alone): Storybook’s root often has no
       definite height, and % / flex children do not resolve against min-height. */
    position: relative;
    display: flex;
    overflow: hidden;
    height: 100vh;
    height: 100dvh;
    max-height: 100vh;
    max-height: 100dvh;
    flex-direction: column;
}

/*
 * Layout containment lives on the inner surface so fixed Drawers/Modals stay
 * clipped to the chat widget, while Select/Popover menus can portal to the
 * outer .memori-widget (MemoriUIProvider container) without the left-offset bug.
 */
.memori-widget__surface {
    position: relative;
    display: flex;
    width: 100%;
    height: 100%;
    min-height: 0;
    flex: 1 1 0%;
    flex-direction: column;
}

/*
 * Nested dialogs: use Modal stacking="stacked" from @memori.ai/ui (z-index 1600).
 * Do not reintroduce max int z-index overrides here.
 */

.memori.memori-widget.memori-layout-chat > .memori-widget__surface,
.memori.memori-widget.memori-layout-fullpage > .memori-widget__surface,
.memori.memori-widget.memori-layout-zoomed_full_body > .memori-widget__surface {
    contain: layout;
}

/* After inserting .memori-widget__surface, Spin is no longer a direct child of
   .memori-widget — keep it a stretching flex column so fullpage/chat fill the viewport. */
.memori-widget > .memori-widget__surface > .memori-spin {
    position: relative;
    display: flex !important;
    overflow: hidden;
    width: 100%;
    height: 100% !important;
    min-height: 0;
    flex: 1 1 0% !important;
    flex-direction: column !important;
}

.memori-widget > .memori-widget__surface > .memori-spin > .memori-fullpage-content-row,
.memori-widget > .memori-widget__surface > .memori-spin.memori-chat-layout > .memori-chat-layout--main {
    height: 100% !important;
    min-height: 0;
    flex: 1 1 0% !important;
}

.memori-widget > .memori-widget__surface > .memori-spin > .memori-fullpage-top-header {
    flex-shrink: 0;
}

/* --- 6. Base: brand e tema di default (in layer così overrides possono sovrascrivere --memori-primary) ---
 * Rebind primary-derived tokens on host scopes (not only :root). Embeds set
 * --memori-primary-color on .memori-widget; tokens computed only on :root stay
 * frozen to the default brand, so disabled/soft/subtle UI would ignore the
 * integration color. Formulas match @memori.ai/ui theme tokens. */
@layer memori.overrides {
    :root,
    body,
    memori-client,
    .memori-widget,
    #headlessui-portal-root,
    #storybook-root,
    #storybook-docs,
    memori-client #root,
    body.sb-show-main #root {
        --memori-primary-color: rgb(var(--memori-primary-rgb, 130 70 175));
        --memori-primary: var(--memori-primary-color);
        --memori-primary-hover: color-mix(in oklch, var(--memori-primary), black 15%);
        --memori-primary-active: color-mix(in oklch, var(--memori-primary), black 20%);
        --memori-primary-disabled: color-mix(in oklch, var(--memori-primary), transparent 60%);
        --memori-primary-subtle: color-mix(in oklch, var(--memori-primary), white 88%);
        --memori-primary-subtle-hover: color-mix(in oklch, var(--memori-primary), white 78%);
        --memori-primary-alpha: color-mix(in oklch, var(--memori-primary) 15%, transparent);
        --memori-border-primary: color-mix(in oklch, var(--memori-primary), transparent 70%);
        --memori-border-primary-hover: color-mix(in oklch, var(--memori-primary), transparent 50%);
        --memori-focus-ring-color: color-mix(in oklch, var(--memori-primary), transparent 55%);
        --memori-focus-ring: 0 0 0 3px var(--memori-focus-ring-color);
        --memori-shadow-primary: 0 8px 16px -4px color-mix(in oklch, var(--memori-primary), transparent 70%);
        /* Text-derived: @memori.ai/ui computes this on :root only, so a dark
           widget inside a light page would inherit the light ink. Rebind here
           so it follows the widget's own --memori-text-color. */
        --memori-icon-button-icon: color-mix(in oklch, var(--memori-text-color) 72%, transparent);
        --memori-layout-max-width: 1280px;
        /* Shared conversation axis (message list, empty state, input) */
        /* Input width. The chat body adds 2 × inline padding (32px),
           so 63rem yields body 1040px and input 1008px. */
        --memori-conversation-max-width: 63rem; /* 1008px */
        --memori-conversation-inline-padding: var(--memori-spacing-md);
        font-family: var(--memori-font-family, 'Lexend Deca', sans-serif);
        font-size: var(--memori-text-size-md);
    }
}

/* --- 7. Colore testo custom in light (prima del dark per specificità) --- */
.memori-widget {
    /* --memori-text-color: var(--memori-integration-text-color, var(--memori-text-color)); */
    /* max-width: var(--memori-layout-max-width); */
    margin: 0 auto;
    background-color: var(--memori-secondary-background);
}

/* --- 8. Dark mode: surface contrast + primary-derived rebinds (keep brand on --memori-primary-color) --- */
@layer memori.overrides {
    [data-theme='dark'] memori-client,
    [data-theme='dark'] memori-client #root,
    [data-theme='dark'] #headlessui-portal-root,
    [data-theme='dark'] .memori-widget,
