___CSS_LOADER_EXPORT___.push([module.id, `/**
 * ArtifactActions CSS Styles
 * Following the project's design system and CSS patterns
 */

.memori-artifact-action-btn {
    position: relative;
    display: flex;
    width: 100%;
    align-items: center;
    justify-content: flex-start;
    padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs)) var(--memori-spacing-md);
    border: none;
    background: none;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: var(--memori-text-size-sm);
    text-align: left;
    transition: background-color 0.15s ease;
}

.memori-artifact-action-icon,
.memori-artifact-action-icon-fullscreen {
    width: 16px;
    height: 16px;
    color: inherit;
    fill: none;
    stroke: currentColor;
}

.memori-artifact-action-icon {
    color: var(--memori-text-color);
}

.memori-artifact-action-text {
    font-size: 0.75rem;
    font-weight: var(--memori-text-weight-medium);
}

/* Responsive Design */

@media (max-width: 768px) {
    .memori-artifact-action-btn {
        min-width: 2.5rem;
        justify-content: center;
        padding: 0.5rem;
    }

    .memori-artifact-actions-row {
        gap: 0 var(--memori-spacing-xs);
    }
}

@media (max-width: 480px) {
    .memori-artifact-actions-row {
        gap: 0 var(--memori-spacing-xs);
    }

    .memori-artifact-action-btn {
        min-width: 2.25rem;
        padding: 0.375rem;
        font-size: 0.75rem;
    }
}

/* Loading State */

/* Icon Sizing */
.memori-artifact-action-btn .memori-button--icon,
.memori-artifact-action-icon-fullscreen {
    font-size: var(--memori-text-size-md);
    line-height: 1;
}

/* Animation for Copy Feedback */
@keyframes copyFeedback {
    0% {
        opacity: 1;
        transform: scale(1);
    }
    50% {
        opacity: 0.8;
        transform: scale(1.05);
    }
    100% {
        opacity: 1;
        transform: scale(1);
    }
}

.memori-artifact-action-btn.copied {
    animation: copyFeedback 0.3s ease;
}

/* Tooltip Support */
.memori-artifact-action-btn[title] {
    position: relative;
}

/* Horizontal Button Row Styles */
.memori-artifact-actions-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--memori-spacing-sm);
}
