    display: flex;
    max-width: 100%;
    flex-direction: column;
    padding: 0;
    border: 0;
    margin: 0;
    gap: 0;
}

/* Form sections: consistent vertical rhythm */
.memori--venue-widget__form-item {
    margin-bottom: var(--memori-spacing-xl);
}

.memori--venue-widget__form-item:last-child {
    margin-bottom: 0;
}

/* Controls block: search + actions + uncertainty */
.memori--venue-widget__controls {
    display: flex;
    flex-direction: column;
    gap: var(--memori-spacing-lg);
}

.memori--venue-widget__geosuggest {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--memori-spacing-md);
}

.memori--venue-widget__search-wrap {
    min-width: 0;
    flex: 1 1 auto;
}

.memori--venue-widget__gps-button {
    flex-shrink: 0;
    padding: var(--memori-spacing-sm) var(--memori-spacing-lg);
}

.memori--venue-widget__updating-message {
    padding: var(--memori-spacing-sm) 0;
    margin: 0;
}

.memori--venue-widget__actions {
    margin-top: 0;
}

.memori--venue-widget__no-location-button {
    width: 100%;
    max-width: 20rem;
}

.memori--venue-widget__uncertainty-wrap {
    margin-top: 0;
}

.memori--venue-widget__select-label {
    display: inline-flex;
    align-items: center;
    gap: var(--memori-spacing-xs);
}

.memori--venue-widget__uncertainty {
    margin-inline: 0;
}

@media (max-width: 640px) {
    .memori--venue-widget__geosuggest {
        flex-direction: column;
        align-items: stretch;
        gap: var(--memori-spacing-sm);
    }

    .memori--venue-widget__gps-button {
        width: 100%;
    }

    .memori--venue-widget__no-location-button {
        max-width: none;
    }
}

/* Map section */
.memori--venue-widget__map-section {
    display: flex;
    flex-direction: column;
    gap: var(--memori-spacing-md);
}

.memori--venue-widget__place-name {
    padding: var(--memori-spacing-sm) 0;
    margin: 0;
    font-size: var(--memori-text-size-md);
    line-height: var(--memori-text-line-normal);
}

.memori--venue-widget__map-container {
    overflow: hidden;
    width: 100%;
    min-height: 200px;
    border-radius: var(--memori-radius-surface);
}

.memori--venue-widget__map {
    width: 100%;
    height: 280px;
}

.memori--venue-widget-search {
    z-index: 1001;
}

.memori--venue-widget-search--label {
    display: inline-block;
    margin-bottom: var(--memori-spacing-sm);
}

.memori--venue-widget-search input,
.memori--venue-widget-search .memori--venue-widget-search--input {
    flex: 1 1 auto;
    padding: calc(var(--memori-spacing-sm) + 2px);
    border: var(--memori-border) solid var(--memori-border-color);
    border-radius: var(--memori-radius-control);
    margin: 0;
    font-size: var(--memori-text-size-md);
    line-height: var(--memori-text-line-normal);
    transition:
        border-color 0.15s ease-in-out,
        box-shadow 0.15s ease-in-out;
}

.memori--venue-widget-search .memori--venue-widget-search--input.memori--venue-widget-search--input-disabled {
    background-color: #f7fafc;
    color: var(--memori-text-color);
    cursor: not-allowed;
}

.memori--venue-widget-search .memori--venue-widget-search--input:focus,
.memori--venue-widget-search button:focus,
.memori--venue-widget-search input:focus {
    border-color: var(--memori-primary);
    box-shadow: 0 2px 0 rgba(0, 0, 0, 0.2);
    outline: none;
}

.memori--venue-widget-search a {
    color: var(--memori-primary);
    text-decoration: underline;
}

ul.memori--venue-widget-search--options {
    position: absolute;
    z-index: 1;
    overflow: auto;
    width: 100%;
    max-width: min(18rem, 30%);
    max-height: 15rem;
    padding-top: var(--memori-spacing-sm);
    padding-right: 0;
    padding-bottom: 0.25rem;
    padding-left: 0;
    border-radius: var(--memori-radius-surface);
    margin-top: var(--memori-spacing-sm);
    margin-right: 0;
    margin-bottom: 0;
    margin-left: 0;
    background: #fff;
    box-shadow:
        rgb(255, 255, 255) 0px 0px 0px 0px,
        rgba(0, 0, 0, 0.05) 0px 0px 0px 1px,
        rgba(0, 0, 0, 0.1) 0px 10px 15px -3px,
        rgba(0, 0, 0, 0.1) 0px 4px 6px -4px;
    list-style: none;
}

@media (min-width: 640px) {
    .memori--venue-widget-search--options {
        font-size: var(--memori-text-size-sm);
        line-height: var(--memori-text-line-tight);
    }
}

.memori--venue-widget-search--option {
    position: relative;
    padding-top: 0.5rem;
    padding-right: 1rem;
    padding-bottom: 0.5rem;
    padding-left: 1rem;
    color: var(--memori-text-color);
    touch-action: none;
    user-select: none;
}

li.memori--venue-widget-search--option {
    cursor: pointer;
    touch-action: initial;
}

li.memori--venue-widget-search--option:hover,
li.memori--venue-widget-search--option:focus {
    background-color: #f7fafc;
}

li.memori--venue-widget-search--option:focus {
    outline: 2px solid #63b3ed;
    outline-offset: 2px;
}

li.memori--venue-widget-search--option--selected {
    background-color: #f7fafc;
}

li.memori--venue-widget-search--option--active {
    background-color: #f7fafc;
}

.memori--venue-widget-search--option-centered {
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
}
