___CSS_LOADER_EXPORT___.push([module.id, `.memori-snippet {
    position: relative;
    overflow: hidden;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
    /* border: 1px solid #e5e7eb; */
    border-radius: var(--memori-radius-surface);
    background: #f8fafc;
}

.memori-snippet--content {
    position: relative;
    display: flex;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
    flex-direction: column;
}

.memori-snippet pre {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
    padding: 1rem;
    border: none;
    border-radius: 0;
    margin: 0;
    background: transparent;
    font-family: 'Fira Code', 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-relaxed);
    overflow-x: auto;
    white-space: pre-wrap;
    word-break: break-word;
    word-wrap: break-word;
}

pre[class*='language-'] {
    margin: 0 !important;
}

/* Override Prism theme defaults (pre/code[class*="language-"]) which force
   white-space: pre and disable word-wrap. Without these overrides, long
   unbreakable tokens make the snippet card overflow its container on mobile. */
.memori-snippet pre[class*='language-'],
.memori-snippet code[class*='language-'] {
    overflow-wrap: anywhere;
    white-space: pre-wrap;
    word-break: break-word;
    word-spacing: normal;
    word-wrap: break-word;
}

.memori-snippet pre[class*='language-'] {
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
    overflow-x: auto;
}
/* Preview mode: full content with max height and scroll */
.memori-snippet--preview .memori-snippet--content {
    display: flex;
    overflow: hidden;
    max-height: 200px;
    flex-direction: column;
}

.memori-snippet--preview .memori-snippet--content pre {
    min-height: 0;
    flex: 1;
    overflow-x: hidden;
    overflow-y: auto;
}

.memori-snippet code {
    display: block;
    max-width: 100%;
    padding: 0;
    border-radius: 0;
    background: transparent;
    color: var(--memori-text-color);
    font-family: inherit;
}

@media (max-width: 768px) {
    .memori-snippet pre {
        padding: 0.875rem;
    }

    .memori-snippet--copy-wrapper {
        right: 0.375rem;
        padding: 0.375rem;
    }
}

.memori-snippet--copy-wrapper {
    position: absolute;
    z-index: 10;
    top: 0.5rem;
    right: 0.5rem;
    display: flex;
    align-items: center;
    padding: 0.5rem;
    border-radius: var(--memori-radius-control);
    gap: var(--memori-spacing-sm);
}

button.memori-snippet--copy-button {
    /* width: 32px !important;
    height: 32px !important; */
    padding: 0;
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: var(--memori-radius-control) !important;
    background: var(--memori-secondary-background);
    transition: all 0.2s ease;
}

button.memori-snippet--copy-button:active {
    /* background: rgba(0, 0, 0, 0.15); */
    transform: scale(0.95);
}

button.memori-snippet--copy-button svg {
    width: 14px;
    height: 14px;
    color: var(--memori-text-color);
}

.memori-snippet button.memori-snippet--copy-button--copied svg {
    color: var(--memori-success, #22c55e);
}

.memori-snippet--caption {
    width: 100%;
    padding: 0.75rem 1rem;
    border-top: 1px solid rgba(0, 0, 0, 0.05);
    margin: 0;
    background: rgba(0, 0, 0, 0.02);
    color: var(--memori-text-color);
    font-size: 0.8rem;
    font-style: normal;
    font-weight: var(--memori-text-weight-medium);
    text-align: left;
}
