.memori--upload-menu-item {
    display: flex;
    align-items: center;
    border-radius: var(--memori-radius-control);
    margin: var(--memori-spacing-xs) var(--memori-spacing-sm);
    cursor: pointer;
    transition: all 0.2s;
}

.memori--upload-menu-item:hover {
