    font-family: monospace;
    line-height: 1.5;
}

.memori--upload-image-preview-modal .memori-modal--panel {
    overflow: hidden;
}

.memori--upload-image-preview-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
    text-align: center;
}

.memori--upload-image-preview-frame {
