    overflow: hidden;
    width: min(72vw, 640px);
    max-width: 100%;
    height: min(42vh, 320px);
    align-items: center;
    justify-content: center;
}

.memori--upload-image-preview {
    width: 100%;
    height: 100%;
    object-fit: contain;
}

