    flex-shrink: 0;
}

.memori-widget
    .memori-chat-inputs--upload-wrapper
    .memori-icon-button.memori-button:not(.memori-button--active, .memori-button--recording),
.memori-widget
    .memori-chat-inputs--mic.memori-icon-button.memori-button:not(.memori-button--active, .memori-button--recording) {
    border-color: transparent;
    background: transparent;
}

