.memori-widget.memori-layout-zoomed_full_body .memori-chat-inputs--container {
    min-height: 0;
    padding: 12px;
}

.memori-widget.memori-layout-hidden_chat .memori-chat-inputs--container,
.memori-widget.memori-layout-website_assistant .memori-chat-inputs--container,
.memori-widget.memori-layout-chat .memori-chat-inputs--container {
    min-height: 0;
    padding: 12px;
}

/* Keep disclaimer + brand on the same axis as the input pill */
.memori-widget.memori-layout-fullpage .memori-conversation-footer,
.memori-widget.memori-layout-zoomed_full_body .memori-conversation-footer {
    max-width: 100%;
}

@media (max-width: 768px) {
    .memori-conversation-footer {
        justify-content: center;
        gap: 0;
    }

    .memori-widget.memori--active .memori-conversation-footer {
        justify-content: flex-start;
