___CSS_LOADER_EXPORT___.push([module.id, `.memori-side-drawer.memori-drawer {
    display: flex;
    min-height: 0;
    flex-direction: column;
}

/*
 * Open state is translate(0) in the design system, which still creates a
 * containing block. Select lists inside the panel are position:fixed and
 * placed with viewport coordinates, so that identity transform shifts them
 * off the panel. none matches the open position and keeps the slide transition.
 */
.memori-side-drawer.memori-drawer[data-state='open'] {
    transform: none;
}

.memori-side-drawer .memori-drawer__header {
    align-items: flex-start;
    gap: var(--memori-spacing-md);
}

.memori-side-drawer .memori-drawer__header > :first-child {
    min-width: 0;
    flex: 1 1 auto;
}

.memori-side-drawer .memori-drawer__title {
    font-size: var(--memori-text-size-2xl);
}

.memori-side-drawer .memori-drawer__description {
    color: color-mix(in oklch, var(--memori-text-color) 64%, transparent);
}

.memori-side-drawer .memori-drawer__body {
    display: flex;
    overflow: hidden;
    min-height: 0;
    flex: 1 1 auto;
    flex-direction: column;
    padding: 0;
    padding-bottom: var(--memori-spacing-lg);
}

.memori-side-drawer__body {
    display: flex;
    overflow: auto;
    min-height: 0;
    flex: 1 1 auto;
    flex-direction: column;
    padding: var(--memori-spacing-md) var(--memori-spacing-lg);
    gap: var(--memori-spacing-md);
    scrollbar-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 55%, transparent) transparent;
    scrollbar-width: thin;
}

.memori-side-drawer__body::-webkit-scrollbar {
    width: 8px;
}

.memori-side-drawer__body::-webkit-scrollbar-track {
    background: transparent;
}

.memori-side-drawer__body::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 45%, transparent);
}

.memori-side-drawer__body::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 60%, transparent);
}

.memori-side-drawer .memori-drawer__footer {
    display: block;
    justify-content: stretch;
    padding: var(--memori-spacing-md) var(--memori-spacing-lg);
}

.memori-side-drawer .memori-drawer__footer .memori-drawer-footer {
    width: 100%;
    padding: 0;
    border-top: none;
    box-shadow: none;
}

.memori-side-drawer-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: var(--memori-spacing-xl) var(--memori-spacing-md);
    color: var(--memori-text-color);
    gap: var(--memori-spacing-sm);
    text-align: center;
}

.memori-side-drawer-empty__icon {
    display: inline-flex;
    width: 3.25rem;
    height: 3.25rem;
    align-items: center;
    justify-content: center;
    border-radius: var(--memori-radius-surface);
    margin-bottom: var(--memori-spacing-xs);
    background: var(--memori-main-background);
    color: color-mix(in oklch, var(--memori-text-color) 55%, transparent);
}

.memori-side-drawer-empty__title {
    margin: 0;
    font-size: var(--memori-text-size-lg);
    font-weight: var(--memori-text-weight-semibold);
    line-height: var(--memori-text-line-tight);
}

.memori-side-drawer-empty__text {
    max-width: 22.5rem;
    margin: 0;
    color: color-mix(in oklch, var(--memori-text-color) 64%, transparent);
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-relaxed);
}
