    position: relative;
    display: flex;
    width: 100%;
    height: 100%;
    flex-direction: column;
}

/**
 * Shared conversation axis for CHAT + FULLPAGE:
 * message list, empty/start state and input share one max-width and inline padding.
 * Children must not set their own column max-width / margin-inline.
 */
.memori-conversation-column {
    display: flex;
    width: 100%;
    min-width: 0;
    max-width: var(--memori-conversation-max-width, 48rem);
    height: 100%;
    min-height: 0;
    box-sizing: border-box;
    flex: 1 1 auto;
    flex-direction: column;
    margin-inline: auto;
}

@media (max-width: 768px) {
    .memori-chat--wrapper.chat-focused {
        padding-bottom: 0;
    }
}

.memori-chat--history {
    position: relative;
    overflow: hidden;
    width: 100%;
    height: calc(100% - 50px);
    min-height: 0;
    flex: 1;
    border-radius: var(--memori-radius-surface) var(--memori-radius-surface) 0 0;
    margin-bottom: 1rem;
    background-color: var(--memori-secondary-background);
}

.memori-chat--history:has(.memori-chat--content--has-global-background) {
    background-color: transparent;
}

/* Adjust chat history when textarea is expanded */
.memori-chat-wrapper--expanded .memori-chat--history {
    margin-bottom: var(--memori-spacing-sm);
}

.memori-chat--history.memori-chat--history-touch {
    height: 80% !important;
    padding: 0;
}

.memori-chat--content {
    position: relative;
    display: flex;
    height: 100%;
    min-height: 0;
    flex: 1;
    flex-direction: column;
    overflow-anchor: none;
    /* background-color: var(--memori-secondary-background); */
    /* padding: 2rem var(--memori-spacing-sm); */
    /* mask-image: linear-gradient(transparent, black 5%, black 95%, transparent 100%); */
    overflow-y: auto;
    /* auto avoids Safari flash on programmatic scrollTop / late image layout */
    scroll-behavior: auto;
    scrollbar-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 55%, transparent) transparent;
    scrollbar-width: thin;
}

/* Prevent WebKit from shrinking message children inside the scroll flex column */
.memori-chat--content > * {
    min-width: 0;
    max-width: 100%;
    flex-shrink: 0;
}

.memori-chat--content::-webkit-scrollbar {
    width: 8px;
}

.memori-chat--content::-webkit-scrollbar-track {
    background: transparent;
}

.memori-chat--content::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 45%, transparent);
}

.memori-chat--content::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 60%, transparent);
}

/* Conversation-column overrides sit between base and layout-scoped rules. */
.memori-conversation-column .memori-chat--wrapper,
.memori-conversation-column .memori-chat--history,
.memori-conversation-column .memori-chat--content,
.memori-conversation-column .memori-chat-inputs-wrapper,
.memori-conversation-column .memori-chat-inputs,
.memori-conversation-column .memori-chat-inputs--ai-note,
.memori-conversation-column .memori--start-panel,
.memori-conversation-column .memori-chat-layout--body,
.memori-conversation-column .memori-chat-layout--start-shell,
.memori-conversation-column .memori-chat-layout--start-panel-wrap {
    width: 100%;
    max-width: none;
    margin-inline: 0;
}

.memori-chat--content.memori-chat--content-touch {
    padding-bottom: 0;
    padding-inline: 0;
}

.memori-conversation-column .memori-chat--content,
.memori-conversation-column .memori-chat--content.memori-chat--content-touch {
    padding-top: var(--memori-spacing-lg);
    padding-inline: 0;
}

.memori-conversation-column .memori-chat-inputs-wrapper {
    padding-inline: 0;
}

/* Solo widget layout CHAT: area messaggi a card — top radius only;
   bottom radius lives on the input bar so the panel reads as one unit */
.memori-widget.memori-layout-chat .memori-chat-layout--controls .memori-chat--history {
    height: 100%;
    min-height: 0;
    padding: 0;
    border-radius: 0;
    margin: 0;
    background-color: var(--memori-secondary-background);
    box-shadow: none;
}

.memori-widget.memori-layout-chat
    .memori-chat-layout--controls
    .memori-chat--history:has(.memori-chat--content--has-global-background) {
    background-color: transparent;
}

.memori-widget.memori-layout-chat .memori-widget {
    padding: 0;
}

.memori-widget.memori-layout-chat .memori-chat--bubble:not(.memori-chat--user-bubble) {
    border: none;
    /* background-color: var(--memori-secondary-background); */
}

.memori-widget.memori-layout-chat .memori-media-item--document {
    background-color: var(--memori-secondary-background);
}

.memori-chat--content--has-global-background {
    background-color: transparent;
}

/* Global background image lives on the chat history area (not the whole layout),
   which is the messages viewport and does not scroll: the image therefore stays
   put while messages scroll over it. Pseudo-element keeps blur off the messages. */
.memori-chat--history--has-global-background {
    isolation: isolate;
}

.memori-chat--history--has-global-background::before {
    position: absolute;
    z-index: 0;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background-color: #eee;
    background-image: var(--memori-chat-global-background);
    background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
    content: '';
    filter: blur(5px);
    pointer-events: none;
    transform: scale(1.06);
}

.memori-chat--history--has-global-background > * {
    position: relative;
    z-index: 1;
}

.memori-chat--jump-to-latest {
    position: absolute;
    z-index: 4;
    right: 0;
    bottom: 0.75rem;
    left: 0;
    display: flex;
    justify-content: center;
    pointer-events: none;
}

.memori-chat--jump-to-latest-btn {
    display: inline-flex;
    width: 2.25rem;
    height: 2.25rem;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 1px solid color-mix(in oklch, var(--memori-text-color) 14%, transparent);
    border-radius: 999px;
    background: var(--memori-secondary-background, #fff);
    box-shadow: 0 0.5rem 1.25rem color-mix(in oklch, #000 16%, transparent);
    color: var(--memori-text-color);
    cursor: pointer;
    pointer-events: auto;
}

.memori-chat--jump-to-latest-btn:hover {
    background: color-mix(in oklch, var(--memori-text-color) 6%, var(--memori-secondary-background, #fff));
}

.memori-chat--jump-to-latest-btn:focus-visible {
    outline: 2px solid var(--memori-primary, #1890ff);
    outline-offset: 2px;
}

.memori-chat--jump-to-latest-typing {
    display: inline-flex;
    align-items: center;
    font-size: 0.5rem;
    gap: 3px;
}

.memori-chat--jump-to-latest-typing-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--memori-primary);
}

[data-theme='dark'] .memori-chat--jump-to-latest-typing-dot {
    background: #fff;
}

@media (prefers-reduced-motion: no-preference) {
    .memori-chat--jump-to-latest-typing-dot {
        animation: memori-wave 1.5s linear infinite;
    }

    .memori-chat--jump-to-latest-typing-dot:nth-child(2) {
        animation-delay: -1.3s;
    }

    .memori-chat--jump-to-latest-typing-dot:nth-child(3) {
        animation-delay: -1.1s;
    }
}

/* Ensure smooth scrolling on mobile */
/* @media (max-width: 768px) {
    .memori-chat--content {
        padding: 1rem var(--memori-spacing-xs);
    }
} */

@media (max-width: 480px) {
    .memori-fullpage-header-brand-name {
        font-size: 1.1rem !important;
    }
}

.memori-chat--cover {
    position: relative;
    width: 100%;
    padding-top: 24.25%;
    margin-top: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs) / 2);
    margin-top: 0;
    margin-bottom: var(--memori-spacing-lg);
    background-position: center;
    background-size: cover;
    border-top-left-radius: 12px;
    border-top-right-radius: 12px;
}

/* Hide the initial divider when there is a cover (works even with MediaWidget before first ChatBubble) */
.memori-chat--cover ~ .memori-chat--bubble-initial {
    display: none;
}

.memori-chat--timestamp {
    display: block;
    padding: 0 3.5rem;
    margin-bottom: var(--memori-spacing-sm);
    color: color-mix(in srgb, var(--memori-text-color) 75%, transparent);
    font-size: 0.75rem;
    font-weight: var(--memori-text-weight-medium, 500);
    line-height: 1.25;
}

.memori-chat--timestamp.text-left {
    text-align: left;
}

.memori-chat--timestamp.text-right {
    text-align: right;
}

.memori-chat--context-vars {
    padding: 0 calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    margin-bottom: var(--memori-spacing-sm);
}

.memori-chat--context-tag {
    display: inline-flex;
    align-items: center;
    padding: 0.25rem 0.75rem;
    border-radius: var(--memori-radius-control);
    margin-right: var(--memori-spacing-sm);
    box-shadow: 0 0 0.25rem var(--memori-primary);
    color: var(--memori-text-color);
    font-size: 0.75rem;
}

.memori-chat--context-tag:focus-within {
    border: 1px solid var(--memori-primary);
    box-shadow: none;
}

.memori-chat--context-tag.memori-chat--context-tag-canceled {
    opacity: 0.7;
    text-decoration: line-through 1.5px;
}

.memori-chat--context-tag-text {
    display: inline-block;
    overflow: hidden;
    max-width: 200px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.memori-chat--context-tag + .memori-chat--context-tag {
    margin-top: var(--memori-spacing-sm);
}

.memori-chat--known-tags {
    display: flex;
    flex-wrap: wrap;
    margin-bottom: var(--memori-spacing-lg);
}

.memori-chat--known-tag {
    margin-right: var(--memori-spacing-sm);
}

/* Drag and drop overlay — always dark; use light content color (not --memori-text-color) */
.memori-chat--drag-overlay {
    position: absolute;
    z-index: 1000;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    border-radius: var(--memori-radius-overlay);
    background-color: rgba(0, 0, 0, 0.7);
    pointer-events: none;
}

.memori-chat--drag-overlay-icon {
    width: 64px;
    height: 64px;
    margin-bottom: 1rem;
    color: var(--memori-primary-content, #fff);
    opacity: 0.9;
}

.memori-chat--drag-overlay-text {
    padding: 0 2rem;
    color: var(--memori-primary-content, #fff);
    font-size: var(--memori-text-size-lg);
    font-weight: var(--memori-text-weight-medium);
    text-align: center;
}

.memori-chat--llm-usage {
    margin-top: 0.625rem;
}

.memori-chat--usage-inside-bubble {
    margin-top: 0.25rem;
}

.memori-chat--llm-usage-hr {
    border: 0;
    border-top: 1px solid rgba(148, 163, 184, 0.35);
    margin: 0 0 0.5rem;
}

.memori-chat--llm-usage-hint {
    margin: 0 0 0.5rem;
    color: #64748b;
    font-size: 0.75rem;
}

.memori-chat--llm-usage-badges {
    display: flex;
    flex-wrap: wrap;
    margin-top: 0.5rem;
    gap: 0.375rem;
}

.memori-chat--usage-badge {
    display: inline-flex;
    align-items: center;
    padding: 0.35rem 0.5rem;
    border: 1px solid var(--memori-border-color);
    border-radius: 999px;
    background: transparent;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: 0.75rem;
    gap: 0.25rem;
    line-height: 1;
    transition:
        border-color 0.2s ease,
        background-color 0.2s ease;
}

.memori-chat--usage-badge:hover {
    background-color: var(--memori-secondary-background);
}

.memori-chat--usage-badge:focus-visible {
    outline: 2px solid var(--memori-primary);
    outline-offset: 2px;
}

.memori-chat--usage-badge-value {
    font-weight: 600;
}

.memori-chat--usage-details {
    margin: 0;
}

.memori-chat--usage-details div {
    display: flex;
    justify-content: space-between;
    padding: 0.375rem 0;
    gap: 1rem;
}

.memori-chat--usage-details dt {
    color: #64748b;
    font-size: 0.875rem;
}

.memori-chat--usage-details dd {
    margin: 0;
    color: var(--memori-text-color);
    font-size: 0.875rem;
    font-weight: 600;
    text-align: right;
}

.memori-chat--usage-educational-content {
    display: flex;
    flex-direction: column;
    padding-top: 0.25rem;
    gap: 0.5rem;
}

.memori-chat--usage-metric-value {
    display: block;
    margin: 0;
    color: var(--memori-text-color);
    font-size: 1.125rem;
}

.memori-chat--usage-comparable {
    margin: 0;
    color: #374151;
    font-size: 0.875rem;
}

.memori-chat--usage-educational-content p {
    margin: 0;
}
