___CSS_LOADER_EXPORT___.push([module.id, `/* Click-to-record: tooltip chrome only — button look owned by IconButton */

.memori-chat-inputs--mic-tooltip.memori-tooltip {
    vertical-align: middle;
}

.memori-chat-inputs--mic-tooltip .memori-tooltip--content {
    overflow: visible;
    max-height: none;
}

.memori-chat-inputs--mic {
    z-index: 1;
    flex-shrink: 0;
    margin-left: 0;
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
    -webkit-touch-callout: none;
    -webkit-user-drag: none;
    user-select: none;
}

.memori-chat-inputs--mic-tooltip.memori-tooltip--align-topLeft .memori-tooltip--content {
    top: -50%;
    right: 115%;
    width: 100%;
    height: 100%;
    min-height: 35px;
    background: rgba(0, 0, 0, 0.8);
    color: #fff;
    font-size: 0.85em;
    opacity: 0;
    text-align: center;
    transform: translateY(-100%);
}
