.memori--preview-container {
    position: relative;
    z-index: 10;
    overflow: hidden;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    border-radius: var(--memori-radius-surface);
    background: transparent;
}

.memori--preview-list {
    display: flex;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
    flex-direction: row;
    flex-wrap: nowrap;
    padding: 0.875rem;
    padding-bottom: 0.625rem;
    gap: 8px;
    -webkit-overflow-scrolling: touch;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scrollbar-color: hsla(var(--border-300) / 35%) transparent;
    scrollbar-width: thin;
    touch-action: pan-x;
}

.memori--document-count {
    position: absolute;
    z-index: 5;
    top: 8px;
    right: 8px;
    padding: calc(var(--memori-spacing-xs) / 4) calc(var(--memori-spacing-xs) + 2px);
    border-radius: var(--memori-radius-control);
    background: color-mix(in srgb, var(--memori-text-color) 6%, var(--memori-secondary-background));
    color: color-mix(in srgb, var(--memori-text-color) 72%, transparent);
    font-size: 12px;
    font-weight: 550;
    /* font-weight: bold; */
}

.memori--document-count-full {
    background-color: #fa5252;
}

.memori--preview-container:has(.memori--document-count) .memori--preview-list {
    padding-right: 2.75rem;
}

.memori--preview-retention-notice {
    display: block;
    margin-top: 8px;
    margin-left: 8px;
    color: color-mix(in srgb, var(--memori-text-color) 52%, transparent);
    font-size: var(--memori-text-size-xs);
}

.memori--preview-item {
    position: relative;
    display: flex;
    width: 120px;
    height: 120px;
    flex-shrink: 0;
    align-items: stretch;
}

.memori--preview-item-trigger {
    display: block;
    overflow: hidden;
    width: 100%;
    min-width: 0;
    height: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    cursor: pointer;
    font: inherit;
    text-align: left;
}

.memori--preview-item--document .memori--preview-item-trigger {
    width: 100%;
    min-width: 0;
    max-width: none;
}

.memori--preview-item--document .memori-media-item--document {
    width: 120px;
    min-width: 120px;
    max-width: 120px;
    height: 120px;
    min-height: 120px;
    box-sizing: border-box;
    /* background: transparent; */
}

.memori--preview-item--skeleton .memori-media-item--document {
    width: 120px;
    min-width: 120px;
    max-width: 120px;
    height: 120px;
    min-height: 120px;
    /* background: transparent; */
}

.memori--preview-item--document .memori-media-item--document:hover {
    box-shadow: none;
}

.memori--preview-item--image .memori--preview-thumbnail {
    display: flex;
    overflow: hidden;
    width: 120px;
    height: 120px;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    background: transparent;
}

.memori--preview-item--image .memori--preview-thumbnail img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.memori--preview-file-info {
    display: flex;
    overflow: hidden;
    min-width: 0;
    flex: 1;
    flex-direction: column;
}

.memori-modal--title {
    overflow: visible;
    max-width: 100%;
    overflow-wrap: anywhere;
    white-space: normal;
    word-break: break-word;
}

.memori--modal-title-preview {
    margin-top: 12px;
    margin-bottom: 12px;
    font-size: 20px;
    font-weight: 600;
}

.memori--remove-button {
    position: absolute;
    z-index: 2;
    top: -8px;
    right: -8px;
    width: 28px !important;
    height: 28px !important;
    min-height: 28px !important;
    padding: 0 !important;
    border: 1px solid var(--memori-border-color) !important;
    border-radius: 50%;
    background: var(--memori-main-background) !important;
    box-shadow: none !important;
    color: var(--memori-text-color) !important;
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition: none;
}

.memori--remove-button:hover,
.memori--remove-button:focus-visible {
    background: var(--memori-secondary-background) !important;
}

.memori--preview-item:hover .memori--remove-button,
.memori--preview-item:focus-within .memori--remove-button {
    opacity: 1;
    pointer-events: auto;
}

.memori--remove-button svg {
    width: 14px;
    height: 14px;
}

@media (max-width: 480px) {
    .memori--remove-button {
        opacity: 1;
        pointer-events: auto;
    }
}

.memori--modal-preview-file {
    width: 100%;
    height: 100%;
    padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
}

.memori--preview-content {
    padding: 0;
    border-radius: var(--memori-radius-surface);
    font-family: monospace;
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-normal);
}

.memori--preview-item--skeleton {
    width: 120px;
    height: 120px;
    cursor: default;
    pointer-events: none;
}

.memori--skeleton-icon {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    border-radius: 4px;
    animation: memori-skeleton-pulse 1.5s ease-in-out infinite;
    background: linear-gradient(90deg, #e9ecef 25%, #f1f3f5 50%, #e9ecef 75%);
    background-size: 200% 100%;
}

.memori--skeleton-line {
    border-radius: 4px;
    animation: memori-skeleton-pulse 1.5s ease-in-out infinite;
    background: linear-gradient(90deg, #e9ecef 25%, #f1f3f5 50%, #e9ecef 75%);
    background-size: 200% 100%;
}

.memori--skeleton-line--name {
    width: 80px;
    height: 12px;
    margin-bottom: 6px;
}

.memori--skeleton-line--type {
    width: 40px;
    height: 10px;
}

@keyframes memori-skeleton-pulse {
    0% {
        background-position: 200% 0;
    }

    100% {
        background-position: -200% 0;
    }
}

@media (max-width: 768px) {
    .memori--preview-container {
        margin-bottom: var(--memori-spacing-sm);
    }

    .memori--preview-retention-notice {
        display: none;
    }
}

@media (max-width: 480px) {
    .memori--preview-container {
        margin-bottom: var(--memori-spacing-sm);
    }
}
