    display: inline-flex;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.blocked-memori-badge {
    display: flex;
    width: 1.25rem;
    height: 1.25rem;
    align-items: center;
    justify-content: center;
    border: 1.5px solid #ffe58f;
    border-radius: 50%;
    background: #fffbe6;
}

.blocked-memori-badge.margin-left {
    margin-left: var(--memori-spacing-sm);
}

.blocked-memori-badge--icon {
    width: 0.75rem;
    height: 0.75rem;
    color: #d48806;
    cursor: pointer;
    fill: none;
    font-size: var(--memori-text-size-md);
    stroke: currentColor;
}

.blocked-memori-badge--tooltip {
    display: inline-flex;
    align-items: center;
    cursor: pointer;
}

.blocked-memori-badge--title {
    margin-left: var(--memori-spacing-sm);
}
