___CSS_LOADER_EXPORT___.push([module.id, `.memori-drawer-footer {
    flex-shrink: 0;
    padding: var(--memori-spacing-md);
    border-top: 1px solid var(--memori-border-color, #e5e7eb);
    box-shadow:
        0 -8px 24px -8px rgba(0, 0, 0, 0.06),
        0 -2px 8px -2px rgba(0, 0, 0, 0.03);
}

.memori-drawer-footer__inner {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--memori-spacing-lg);
}

.memori-drawer-footer__start {
    display: flex;
    align-items: center;
    gap: var(--memori-spacing-md);
}

.memori-drawer-footer__end {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    margin-left: auto;
    gap: var(--memori-spacing-md);
}

.memori-drawer-footer__end .memori-button {
    min-height: 44px;
    padding: 10px var(--memori-spacing-lg);
    border-radius: var(--memori-radius-control);
    font-weight: 500;
    transition: box-shadow 0.15s ease;
}

.memori-drawer-footer__inner--centered {
    justify-content: center;
}

@media (max-width: 768px) {
    .memori-drawer-footer {
        padding: var(--memori-spacing-md) var(--memori-spacing-lg);
    }

    .memori-drawer-footer__inner {
        flex-direction: row;
        align-items: center;
        gap: var(--memori-spacing-md);
    }

    .memori-drawer-footer__end {
        justify-content: flex-end;
        margin-left: 0;
    }
}
