___CSS_LOADER_EXPORT___.push([module.id, `.memori-widget {
    position: relative;
    width: 100%;
    padding: var(--memori-spacing-md);
}

.memori-widget,
.memori-widget * {
    box-sizing: border-box;
}

.memori-widget > .memori-spin,
.memori-widget > .memori-widget__surface > .memori-spin {
    height: calc(100vh - 50px);
}

@media (max-width: 425px) {
    .memori-widget {
        overflow-y: hidden;
    }
    .memori-widget > .memori-spin,
    .memori-widget > .memori-widget__surface > .memori-spin {
        height: calc(100vh - 100px);
    }
}

.memori--grid {
    display: flex;
    height: calc(100% - 50px);
    align-items: center;
    justify-content: space-between;
}

@media (max-width: 870px) {
    .memori--grid {
        flex-direction: column;
        align-items: flex-start;
        justify-content: flex-start;
        overflow-x: visible;
        overflow-y: hidden;
    }
}

.memori--embed .memori--grid .memori--chat-history {
    max-height: 100%;
    overflow-x: visible;
    overflow-y: scroll;
}

.memori--grid-column {
    display: flex;
    width: 100%;
    height: 100%;
    flex-direction: column;
    align-items: flex-start;
}

.memori--grid-column-left {
    position: relative;
    width: 50%;
    margin-right: var(--memori-spacing-lg);
}

@media (max-width: 870px) {
    .memori--grid-column-left {
        display: none;
        width: 100%;
        height: auto;
        max-height: 200px;
        margin-right: 0;
        margin-bottom: var(--memori-spacing-lg);
    }
}

.memori--grid-column-right {
    width: 50%;
    margin-left: var(--memori-spacing-lg);
}

@media (max-width: 870px) {
    .memori--grid-column-right {
        width: 100%;
        margin-left: 0;
    }
}

@media (max-width: 870px) {
    .memori--active .memori--grid-column-right {
        overflow-x: hidden;
        overflow-y: scroll;
    }
}

.memori--select {
    margin-top: var(--memori-spacing-lg);
}

.memori--select label {
    margin: var(--memori-spacing-sm) 0 var(--memori-spacing-xs);
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-normal);
}

.memori--select select {
    display: block;
    width: 100%;
}

.memori--global-background {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100vh;
    height: 100dvh;
    min-height: 100vh;
    background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
}

.memori--global-background-image {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    min-height: 100vh;
    min-height: 100dvh;
    background-color: #eee;
    background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
    filter: blur(0);
}

@media (max-width: 870px) {
    .memori--global-background-image {
        min-height: 100vh;
    }
}

.memori--conversation-button {
    z-index: 1;
}

.memori--conversation-button svg {
    width: 1rem;
    height: 1rem;
    font-size: var(--memori-text-size-md);
}

.memori--conversation-button + .memori--conversation-button {
    margin-left: var(--memori-spacing-xs);
}

.memori.memori-widget.chat-focused .memori--powered-by,
.memori.memori-widget.memori-layout-website_assistant.chat-focused .memori-website_assistant--close-button {
    display: none;
}

.memori-drawer__header {
    align-items: center;
}
