    display: flex;
    overflow: hidden;
    width: min(90vw, 800px);
    min-width: 0;
    max-width: min(90vw, 800px);
    /* Flex item in a centered viewport: content-based min-height grows the
       popup past the screen and hides the close button. Keep it shrinkable. */
    min-height: 0;
    max-height: var(--memori-content-preview-max-height);
    box-sizing: border-box;
    flex-direction: column;
    border-radius: var(--memori-radius-overlay);
    box-shadow:
        0 25px 50px -12px rgba(0, 0, 0, 0.25),
        0 0 0 1px rgba(0, 0, 0, 0.05);
}

@media (min-width: 769px) {
    .memori-content-preview-modal.memori-modal__viewport .memori-modal__popup {
        min-height: min(500px, var(--memori-content-preview-max-height));
    }
}

.memori-content-preview-modal.memori-modal__viewport .memori-modal__popup > .memori-spin {
    display: flex;
    overflow: hidden;
    min-width: 0;
    min-height: 0;
    max-height: none;
    flex: 1 1 auto;
    flex-direction: column;
}

.memori-content-preview-modal.memori-modal__viewport .memori-modal__content {
    display: flex;
    overflow: hidden;
    min-width: 0;
    min-height: 0;
    max-height: none;
    flex: 1 1 auto;
    flex-direction: column;
}

/* Image variant: modal at least 600px wide (capped by viewport on small screens) */
.memori-content-preview-modal--image.memori-modal__viewport .memori-modal__popup {
    overflow: hidden;
    min-width: min(600px, 100%);
    max-width: min(90vw, 760px);
    min-height: 0;
}

.memori-modal__viewport.memori-content-preview-modal .memori-modal__title {
    overflow: visible;
    min-width: 0;
    max-width: 100%;
    flex-shrink: 0;
    padding: 1rem 1.25rem 0.75rem;
    padding-right: calc(var(--memori-icon-button-size, 44px) + 1.5rem);
    border-bottom: 1px solid var(--memori-content-preview-border, rgba(0, 0, 0, 0.06));
    margin-bottom: 0;
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-md);
    font-weight: var(--memori-text-weight-semibold);
    letter-spacing: -0.01em;
    line-height: 1.35;
    overflow-wrap: anywhere;
    white-space: normal;
    word-break: break-word;
}

.memori-content-preview-modal--heading {
    display: flex;
    min-width: 0;
    align-items: flex-start;
    gap: 0.75rem;
}

.memori-content-preview-modal--heading-icon {
    display: flex;
    width: 2.5rem;
    height: 2.5rem;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: var(--memori-primary-subtle);
    color: var(--memori-primary);
}

.memori-content-preview-modal--heading-icon svg {
    width: 1.125rem;
    height: 1.125rem;
}

.memori-content-preview-modal--heading-copy {
    display: flex;
    min-width: 0;
    flex: 1;
    flex-direction: column;
    gap: 0.15rem;
}

.memori-content-preview-modal--heading-title {
    min-width: 0;
    color: var(--memori-text-color);
    font-size: var(--memori-text-size-md);
    font-weight: 650;
    letter-spacing: -0.015em;
    line-height: 1.3;
    overflow-wrap: anywhere;
    white-space: normal;
    word-break: break-word;
}

.memori-content-preview-modal--heading-subtitle {
    color: color-mix(in srgb, var(--memori-text-color) 58%, transparent);
    font-size: var(--memori-text-size-sm);
    font-weight: 400;
    line-height: 1.35;
    overflow-wrap: anywhere;
    white-space: normal;
}

.memori-modal__viewport.memori-content-preview-modal .memori-modal__close {
    top: 0.75rem;
    right: 0.75rem;
}

.memori-content-preview-modal--body--image {
