.memori-content-preview-modal--image-wrap {
    display: flex;
    width: min(72vw, 640px);
    min-width: 0;
    max-width: 100%;
    height: min(56vh, 420px);
    height: min(56dvh, 420px);
    min-height: 0;
    max-height: 100%;
    flex: 1 1 auto;
    align-items: center;
    justify-content: center;
}

.memori-content-preview-modal--image {
    width: 100%;
    height: 100%;
    border-radius: var(--memori-radius-surface);
    object-fit: contain;
}

.memori-file-preview-modal.memori-content-preview-modal--image.memori-modal__viewport .memori-modal__popup {
    overflow: hidden;
    background: var(--memori-main-background);
}

.memori-content-preview-modal--scroll-shell {
    position: relative;
    display: flex;
    overflow: hidden;
    min-width: 0;
    min-height: 0;
    flex: 1 1 auto;
    flex-direction: column;
}

.memori-content-preview-modal--scroll-cue {
    position: absolute;
    z-index: 1;
    right: 0;
    bottom: 0;
    left: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2.75rem 1rem 0.85rem;
    border: 0;
    background: linear-gradient(
        to top,
        var(--memori-secondary-background) 0%,
        var(--memori-secondary-background) 38%,
        color-mix(in srgb, var(--memori-secondary-background) 55%, transparent) 72%,
        transparent 100%
    );
    color: color-mix(in srgb, var(--memori-text-color) 52%, transparent);
    cursor: pointer;
    font-family: inherit;
    font-size: var(--memori-text-size-sm);
    font-weight: 500;
    gap: 0.35rem;
    letter-spacing: -0.01em;
}

.memori-content-preview-modal--scroll-cue:hover,
.memori-content-preview-modal--scroll-cue:focus-visible {
    color: color-mix(in srgb, var(--memori-text-color) 78%, transparent);
}

.memori-content-preview-modal--scroll-cue:focus-visible {
    outline: 2px solid var(--memori-primary);
    outline-offset: -2px;
}

.memori-content-preview-modal--scroll-cue-icon {
    width: 1rem;
    height: 1rem;
    flex-shrink: 0;
}

@media (prefers-reduced-motion: reduce) {
    .memori-content-preview-modal--scroll-cue-icon {
        animation: none;
    }
}

/* Snippet / text content area */
.memori-content-preview-modal--snippet-wrap {
    min-width: 0;
    max-width: 100%;
    min-height: 0;
    flex: 1 1 auto;
    padding: 1rem 1.25rem;
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    margin: 1rem 1.25rem;
    background: var(--memori-main-background);
    color: var(--memori-text-color);
    font-family: 'SF Mono', 'Fira Code', 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    font-size: var(--memori-text-size-sm);
    line-height: var(--memori-text-line-relaxed);
    overflow-x: auto;
    overflow-y: auto;
    scrollbar-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 55%, transparent) transparent;
    scrollbar-width: thin;
    white-space: pre-wrap;
    word-break: break-word;
}

.memori-content-preview-modal--snippet-wrap--document {
    padding: 1.25rem 1.5rem 2rem;
    border: 0;
    margin: 0;
    background: transparent;
    font-family: var(--memori-font-family);
    font-size: var(--memori-text-size-md);
    line-height: 1.65;
    white-space: normal;
}

.memori-content-preview-modal--scroll-shell--cue .memori-content-preview-modal--snippet-wrap {
    padding-bottom: 3.75rem;
}

/* Rendered markdown */
.memori-content-preview-modal--markdown {
    min-width: 0;
    max-width: 100%;
    color: var(--memori-text-color);
    font-family: var(--memori-font-family);
    font-size: var(--memori-text-size-md);
    line-height: 1.65;
}

.memori-content-preview-modal--markdown > :first-child {
    margin-top: 0;
}

.memori-content-preview-modal--markdown > :last-child {
    margin-bottom: 0;
}

.memori-content-preview-modal--markdown h1,
.memori-content-preview-modal--markdown h2,
.memori-content-preview-modal--markdown h3,
.memori-content-preview-modal--markdown h4,
.memori-content-preview-modal--markdown h5,
.memori-content-preview-modal--markdown h6 {
