    color: var(--memori-text-color);
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.25;
}

.memori-content-preview-modal--markdown h1 {
    margin-top: 0;
    margin-bottom: 0.65rem;
    font-size: 1.75rem;
}

.memori-content-preview-modal--markdown h2 {
    font-size: 1.15rem;
    font-weight: 650;
}

.memori-content-preview-modal--markdown h3 {
    font-size: 1.05rem;
}

.memori-content-preview-modal--markdown p {
    margin: 0 0 0.9rem;
}

.memori-content-preview-modal--markdown strong,
.memori-content-preview-modal--markdown b {
    font-weight: 650;
}

.memori-content-preview-modal--markdown em {
    font-style: italic;
}

.memori-content-preview-modal--markdown a {
    color: var(--memori-primary);
    text-decoration: none;
}

.memori-content-preview-modal--markdown a:hover,
.memori-content-preview-modal--markdown a:focus-visible {
    text-decoration: underline;
}

.memori-content-preview-modal--markdown code {
    padding: 0.12em 0.4em;
    border-radius: 0.4rem;
    background: color-mix(in srgb, var(--memori-text-color) 8%, transparent);
    font-family: 'SF Mono', 'Fira Code', 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    font-size: 0.875em;
}

.memori-content-preview-modal--markdown pre {
    padding: 0.9rem 1rem;
    border-radius: var(--memori-radius-surface);
    margin: 0 0 1rem;
    background: color-mix(in srgb, var(--memori-text-color) 6%, transparent);
    overflow-x: auto;
}

.memori-content-preview-modal--markdown pre code {
    padding: 0;
    background: none;
    font-size: 0.85em;
    white-space: pre;
}

.memori-content-preview-modal--markdown ul,
.memori-content-preview-modal--markdown ol {
    padding-left: 1.25rem;
    margin: 0 0 1rem;
}

.memori-content-preview-modal--markdown li + li {
    margin-top: 0.25rem;
}

.memori-content-preview-modal--markdown blockquote {
    padding: 0.15rem 0 0.15rem 0.9rem;
    border-left: 3px solid color-mix(in srgb, var(--memori-text-color) 18%, transparent);
    margin: 0 0 1rem;
    color: color-mix(in srgb, var(--memori-text-color) 78%, transparent);
}

.memori-content-preview-modal--markdown hr {
    border: 0;
    border-top: 1px solid color-mix(in srgb, var(--memori-text-color) 12%, transparent);
    margin: 1.25rem 0;
}

