.memori-content-preview-modal--truncation-note {
    padding: 0.75rem 0.9rem;
    border-radius: 0 var(--memori-radius-surface) var(--memori-radius-surface) 0;
    border-left: 3px solid color-mix(in srgb, var(--memori-primary) 55%, transparent);
    margin-top: 1.25rem;
    background: color-mix(in srgb, var(--memori-text-color) 5%, transparent);
    color: color-mix(in srgb, var(--memori-text-color) 72%, transparent);
    font-family: var(--memori-font-family);
    font-size: var(--memori-text-size-sm);
    font-weight: 450;
    letter-spacing: -0.01em;
    line-height: 1.5;
}

/* Same DataTable scroll trap as chat: neutralize nested scroll so the modal
   body scrolls when the pointer is over a wide/tall markdown table. */
.memori-content-preview-modal--markdown .memori-table-scroll {
    max-width: 100%;
    max-height: none;
    margin: 0 0 1rem;
    mask-image: none;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    overscroll-behavior-y: auto;
}

.memori-content-preview-modal--markdown table {
    width: 100%;
    margin: 0 0 1rem;
    border-collapse: collapse;
    font-size: 0.95em;
}

.memori-content-preview-modal--markdown .memori-table-scroll > table {
    margin-bottom: 0;
}

.memori-content-preview-modal--markdown th,
.memori-content-preview-modal--markdown td {
    padding: 0.4rem 0.65rem;
    border-bottom: 1px solid color-mix(in srgb, var(--memori-text-color) 10%, transparent);
    text-align: left;
    vertical-align: top;
}

.memori-content-preview-modal--markdown th {
    color: color-mix(in srgb, var(--memori-text-color) 62%, transparent);
    font-weight: 500;
}

/* When Snippet component is used inside, give it consistent spacing */
.memori-content-preview-modal--snippet-wrap .memori-snippet {
    border: none;
    border-radius: var(--memori-radius-surface);
    background: transparent;
    box-shadow: none;
}

.memori-content-preview-modal--snippet-wrap .memori-snippet--content pre {
    padding: 1rem 1.25rem;
    overflow-wrap: break-word;
    /* Override Prism theme so PDF/text content wraps instead of one long line */
    white-space: pre-wrap !important;
    word-break: break-word;
}

.memori-content-preview-modal--snippet-wrap .memori-snippet--content pre code {
    overflow-wrap: break-word;
    white-space: pre-wrap !important;
    word-break: break-word;
}

.memori-content-preview-modal .memori-media-item-preview--content,
.memori-content-preview-modal .memori-media-item--modal-iframe-wrap,
.memori-content-preview-modal .memori-media-item--modal-iframe {
    min-height: 0;
    max-height: none;
    flex: 1 1 auto;
}

@media (max-width: 768px) {
    .memori-content-preview-modal.memori-modal__viewport .memori-modal__popup {
        width: min(92vw, 100%) !important;
        min-width: 0 !important;
        max-width: 100%;
        min-height: 0;
        max-height: var(--memori-content-preview-max-height);
    }

    .memori-content-preview-modal--image.memori-modal__viewport .memori-modal__popup {
        min-width: 0;
    }

    .memori-content-preview-modal--image-wrap {
        width: min(84vw, 520px);
        height: min(48vh, 320px);
        height: min(48dvh, 320px);
        max-height: 100%;
    }

    .memori-content-preview-modal--snippet-wrap {
        padding: 0.75rem;
        margin: 0.75rem;
    }

    .memori-content-preview-modal--snippet-wrap--document {
        padding: 1rem 1.1rem 2rem;
        margin: 0;
    }

    .memori-content-preview-modal--snippet-wrap .memori-snippet {
        min-width: 0;
        max-width: 100%;
    }

    .memori-content-preview-modal--markdown h1 {
        font-size: 1.45rem;
    }
