rt .memori-modal__content {\n    display: flex;\n    overflow: hidden;\n    min-width: 0;\n    min-height: 0;\n    max-height: none;\n    flex: 1 1 auto;\n    flex-direction: column;\n}\n\n/* Image variant: modal at least 600px wide (capped by viewport on small screens) */\n.memori-content-preview-modal--image.memori-modal__viewport .memori-modal__popup {\n    overflow: hidden;\n    min-width: min(600px, 100%);\n    max-width: min(90vw, 760px);\n    min-height: 0;\n}\n\n.memori-modal__viewport.memori-content-preview-modal .memori-modal__title {\n    overflow: visible;\n    min-width: 0;\n    max-width: 100%;\n    flex-shrink: 0;\n    padding: 1rem 1.25rem 0.75rem;\n    padding-right: calc(var(--memori-icon-button-size, 44px) + 1.5rem);\n    border-bottom: 1px solid var(--memori-content-preview-border, rgba(0, 0, 0, 0.06));\n    margin-bottom: 0;\n    color: var(--memori-text-color);\n    font-size: var(--memori-text-size-md);\n    font-weight: var(--memori-text-weight-semibold);\n    letter-spacing: -0.01em;\n    line-height: 1.35;\n    overflow-wrap: anywhere;\n    white-space: normal;\n    word-break: break-word;\n}\n\n.memori-content-preview-modal--heading {\n    display: flex;\n    min-width: 0;\n    align-items: flex-start;\n    gap: 0.75rem;\n}\n\n.memori-content-preview-modal--heading-icon {\n    display: flex;\n    width: 2.5rem;\n    height: 2.5rem;\n    flex-shrink: 0;\n    align-items: center;\n    justify-content: center;\n    border-radius: 12px;\n    background: var(--memori-primary-subtle);\n    color: var(--memori-primary);\n}\n\n.memori-content-preview-modal--heading-icon svg {\n    width: 1.125rem;\n    height: 1.125rem;\n}\n\n.memori-content-preview-modal--heading-copy {\n    display: flex;\n    min-width: 0;\n    flex: 1;\n    flex-direction: column;\n    gap: 0.15rem;\n}\n\n.memori-content-preview-modal--heading-title {\n    min-width: 0;\n    color: var(--memori-text-color);\n    font-size: var(--memori-text-size-md);\n    font-weight: 650;\n    letter-spacing: -0.015em;\n    line-height: 1.3;\n    overflow-wrap: anywhere;\n    white-space: normal;\n    word-break: break-word;\n}\n\n.memori-content-preview-modal--heading-subtitle {\n    color: color-mix(in srgb, var(--memori-text-color) 58%, transparent);\n    font-size: var(--memori-text-size-sm);\n    font-weight: 400;\n    line-height: 1.35;\n    overflow-wrap: anywhere;\n    white-space: normal;\n}\n\n.memori-modal__viewport.memori-content-preview-modal .memori-modal__close {\n    top: 0.75rem;\n    right: 0.75rem;\n}\n\n.memori-content-preview-modal--body--image {\n    display: flex;\n    min-width: 0;\n    min-height: 0;\n    flex: 1 1 auto;\n    align-items: center;\n    justify-content: center;\n    padding: 1rem;\n}\n\n.memori-content-preview-modal--body--content {\n    display: flex;\n    min-width: 0;\n    max-width: 100%;\n    min-height: 0;\n    flex: 1 1 auto;\n    flex-direction: column;\n    padding: 0;\n}\n\n/* Image */\n.memori-content-preview-modal--image-wrap {\n    display: flex;\n    width: min(72vw, 640px);\n    min-width: 0;\n    max-width: 100%;\n    height: min(56vh, 420px);\n    height: min(56dvh, 420px);\n    min-height: 0;\n    max-height: 100%;\n    flex: 1 1 auto;\n    align-items: center;\n    justify-content: center;\n}\n\n.memori-content-preview-modal--image {\n    width: 100%;\n    height: 100%;\n    border-radius: var(--memori-radius-surface);\n    object-fit: contain;\n}\n\n.memori-file-preview-modal.memori-content-preview-modal--image.memori-modal__viewport .memori-modal__popup {\n    overflow: hidden;\n    background: var(--memori-main-background);\n}\n\n.memori-content-preview-modal--scroll-shell {\n    position: relative;\n    display: flex;\n    overflow: hidden;\n    min-width: 0;\n    min-height: 0;\n    flex: 1 1 auto;\n    flex-direction: column;\n}\n\n.memori-content-preview-modal--scroll-cue {\n    position: absolute;\n    z-index: 1;\n    right: 0;\n    bottom: 0;\n    left: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    padding: 2.75rem 1rem 0.85rem;\n    border: 0;\n    background: linear-gradient(\n        to top,\n        var(--memori-secondary-background) 0%,\n        var(--memori-secondary-background) 38%,\n        color-mix(in srgb, var(--memori-secondary-background) 55%, transparent) 72%,\n        transparent 100%\n    );\n    color: color-mix(in srgb, var(--memori-text-color) 52%, transparent);\n    cursor: pointer;\n    font-family: inherit;\n    font-size: var(--memori-text-size-sm);\n    font-weight: 500;\n    gap: 0.35rem;\n    letter-spacing: -0.01em;\n}\n\n.memori-content-preview-modal--scroll-cue:hover,\n.memori-content-preview-modal--scroll-cue:focus-visible {\n    color: color-mix(in srgb, var(--memori-text-color) 78%, transparent);\n}\n\n.memori-content-preview-modal--scroll-cue:focus-visible {\n    outline: 2px solid var(--memori-primary);\n    outline-offset: -2px;\n}\n\n.memori-content-preview-modal--scroll-cue-icon {\n    width: 1rem;\n    height: 1rem;\n    flex-shrink: 0;\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .memori-content-preview-modal--scroll-cue-icon {\n        animation: none;\n    }\n}\n\n/* Snippet / text content area */\n.memori-content-preview-modal--snippet-wrap {\n    min-width: 0;\n    max-width: 100%;\n    min-height: 0;\n    flex: 1 1 auto;\n    padding: 1rem 1.25rem;\n    border: 1px solid var(--memori-border-color);\n    border-radius: var(--memori-radius-surface);\n    margin: 1rem 1.25rem;\n    background: var(--memori-main-background);\n    color: var(--memori-text-color);\n    font-family: 'SF Mono', 'Fira Code', 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;\n    font-size: var(--memori-text-size-sm);\n    line-height: var(--memori-text-line-relaxed);\n    overflow-x: auto;\n    overflow-y: auto;\n    scrollbar-color: color-mix(in oklch, var(--memori-neutral, #6b7280) 55%, transparent) transparent;\n    scrollbar-width: thin;\n    white-space: pre-wrap;\n    word-break: break-word;\n}\n\n.memori-content-preview-modal--snippet-wrap--document {\n    padding: 1.25rem 1.5rem 2rem;\n    border: 0;\n    margin: 0;\n    background: transparent;\n    font-family: var(--memori-font-family);\n    font-size: var(--memori-text-size-md);\n    line-height: 1.65;\n    white-space: normal;\n}\n\n.memori-content-preview-modal--scroll-shell--cue .memori-content-preview-modal--snippet-wrap {\n    padding-bottom: 3.75rem;\n}\n\n/* Rendered markdown */\n.memori-content-preview-modal--markdown {\n    min-width: 0;\n    max-width: 100%;\n    color: var(--memori-text-color);\n    font-family: var(--memori-font-family);\n    font-size: var(--memori-text-size-md);\n    line-height: 1.65;\n}\n\n.memori-content-preview-modal--markdown > :first-child {\n    margin-top: 0;\n}\n\n.memori-content-preview-modal--markdown > :last-child {\n    margin-bottom: 0;\n}\n\n.memori-content-preview-modal--markdown h1,\n.memori-content-preview-modal--markdown h2,\n.memori-content-preview-modal--markdown h3,\n.memori-content-preview-modal--markdown h4,\n.memori-content-preview-modal--markdown h5,\n.memori-content-preview-modal--markdown h6 {\n    margin: 1.35rem 0 0.55rem;\n    color: var(--memori-text-color);\n    font-weight: 700;\n    letter-spacing: -0.02em;\n    line-height: 1.25;\n}\n\n.memori-content-preview-modal--markdown h1 {\n    margin-top: 0;\n    margin-bottom: 0.65rem;\n    font-size: 1.75rem;\n}\n\n.memori-content-preview-modal--markdown h2 {\n    font-size: 1.15rem;\n    font-weight: 650;\n}\n\n.memori-content-preview-modal--markdown h3 {\n    font-size: 1.05rem;\n}\n\n.memori-content-preview-modal--markdown p {\n    margin: 0 0 0.9rem;\n}\n\n.memori-content-preview-modal--markdown strong,\n.memori-content-preview-modal--markdown b {\n    font-weight: 650;\n}\n\n.memori-content-preview-modal--markdown em {\n    font-style: italic;\n}\n\n.memori-content-preview-modal--markdown a {\n    color: var(--memori-primary);\n    text-decoration: none;\n}\n\n.memori-conte