 * CSS styles for artifact copy system components
 * Includes responsive design and print media queries
 */

.memori-copy-button-wrapper {
    --memori-copy-border: color-mix(in oklch, var(--memori-border-color) 82%, transparent);
    --memori-copy-surface: color-mix(in oklch, var(--memori-main-background) 94%, var(--memori-text-color) 6%);
    --memori-copy-surface-hover: color-mix(in oklch, var(--memori-main-background) 88%, var(--memori-primary) 12%);
    --memori-copy-surface-pressed: color-mix(in oklch, var(--memori-main-background) 82%, var(--memori-primary) 18%);
    --memori-copy-text-muted: color-mix(in oklch, var(--memori-text-color) 72%, transparent);
    --memori-copy-shadow:
        0 10px 25px -5px color-mix(in srgb, var(--memori-text-color) 14%, transparent),
        0 10px 10px -5px color-mix(in srgb, var(--memori-text-color) 8%, transparent);
    position: relative;
    display: inline-block;
    margin-left: auto;
}

.memori-copy-button-trigger {
    position: relative;
    padding: 0;
    border: none;
}

/* Copy Button */
.memori-copy-button {
    position: relative;
    display: inline-flex;
    overflow: hidden;
    width: auto;
    min-width: 38px;
    height: 38px;
    min-height: 38px;
    align-items: center;
    padding: 8px 12px;
    border: 1px solid color-mix(in srgb, var(--memori-text-color, #111827) 16%, transparent);
    border-radius: var(--memori-radius-control);
    background: transparent;
    border-bottom-right-radius: 0px;
    border-top-right-radius: 0px;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    gap: var(--memori-spacing-sm);
    line-height: 1.4;
    transition:
        background 0.15s ease,
        color 0.15s ease,
        border-color 0.15s ease;
}

.memori-copy-button:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}

.memori-copy-button:focus-visible {
    outline: 2px solid var(--memori-primary);
    outline-offset: 2px;
}

.memori-copy-button:hover:not(:disabled) {
    border-color: color-mix(in srgb, var(--memori-text-color, #111827) 16%, transparent);
    background: color-mix(in srgb, var(--memori-text-color, #111827) 8%, transparent);
}

.memori-copy-button:active:not(:disabled) {
    border-color: color-mix(in srgb, var(--memori-text-color, #111827) 22%, transparent);
    background: color-mix(in srgb, var(--memori-text-color, #111827) 12%, transparent);
}

.memori-copy-button--success {
    border-color: var(--memori-success);
    /* background: color-mix(in oklch, var(--memori-main-background) 82%, var(--memori-success) 18%); */
    color: var(--memori-text-color);
}

.memori-copy-button--error {
    border-color: var(--memori-error);
    background: color-mix(in oklch, var(--memori-main-background) 84%, var(--memori-error) 16%);
    color: var(--memori-text-color);
}

.memori-copy-button--loading {
    cursor: wait;
}

.memori-copy-button-group {
    display: inline-flex;
    align-items: center;
}

.memori-copy-button--dropdown {
    position: relative;
    display: inline-flex;
    overflow: hidden;
    width: 38px;
    min-width: 38px;
    height: 38px;
    min-height: 38px;
    align-items: center;
    justify-content: center;
    padding: 8px;
    border: 1px solid color-mix(in srgb, var(--memori-text-color, #111827) 16%, transparent);
    border-radius: var(--memori-radius-control);
    background: transparent;
    border-bottom-left-radius: 0px !important;
    border-top-left-radius: 0px !important;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    gap: var(--memori-spacing-sm);
    line-height: 1.4;
    transition:
        background 0.15s ease,
        color 0.15s ease,
        border-color 0.15s ease;
}

.memori-copy-button--dropdown:hover:not(:disabled) {
    border-color: color-mix(in srgb, var(--memori-text-color, #111827) 16%, transparent);
    background: color-mix(in srgb, var(--memori-text-color, #111827) 8%, transparent);
}

/* Button Icons */
.memori-copy-button-icon {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
}

.memori-copy-button-icon--success {
    color: #22c55e;
}

.memori-copy-button-icon--error {
    color: #ef4444;
}

.memori-copy-button-chevron {
    width: 12px;
    height: 12px;
    flex-shrink: 0;
    margin-left: var(--memori-spacing-xs);
    transition: transform 0.2s ease;
}

.memori-copy-button--dropdown:hover .memori-copy-button-chevron {
    transform: rotate(180deg);
}

/* Loading Spinner */
.memori-copy-button-loading {
    display: flex;
    width: 16px;
    height: 16px;
    align-items: center;
    justify-content: center;
}

.memori-copy-button-spinner {
    width: 12px;
    height: 12px;
    border: 2px solid color-mix(in oklch, var(--memori-border-color) 70%, transparent);
    border-radius: 50%;
    border-top-color: var(--memori-primary);
    animation: memori-copy-spin 1s linear infinite;
}

@keyframes memori-copy-spin {
    0% {
        transform: rotate(0deg);
    }
    100% {
        transform: rotate(360deg);
    }
}

/* Copy Menu Wrapper */
.memori-copy-menu-wrapper {
    position: relative;
    z-index: 10;
    display: inline-block;
}

.memori-copy-button--main > .memori-button__content {
    gap: var(--memori-spacing-sm);
}

/* Copy Menu Item */
.memori-copy-menu-item {
    position: relative;
    display: flex;
    width: 100%;
    align-items: center;
    padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs)) var(--memori-spacing-md);
    border: none;
    background: transparent;
    color: var(--memori-text-color);
    cursor: pointer;
    font-size: var(--memori-text-size-sm);
    text-align: left;
    transition:
        background-color 0.15s ease,
        color 0.15s ease;
}

.memori-copy-menu-item:disabled {
    cursor: not-allowed;
    opacity: 0.6;
}

.memori-copy-menu-item:focus-visible {
    outline: 2px solid var(--memori-primary);
    outline-offset: -2px;
}

.memori-copy-menu-item:active:not(:disabled) {
    background: var(--memori-copy-surface-pressed);
}

.memori-copy-menu-item--loading {
    cursor: wait;
}

.memori-copy-menu-item--pdf {
    border-left: 3px solid #3b82f6;
}

.memori-copy-menu-item--print {
    border-left: 3px solid #10b981;
}

.memori-copy-menu-item-content {
    display: flex;
    width: 100%;
    align-items: center;
    gap: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
}

.memori-copy-menu-item-icon-wrapper {
    display: flex;
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
}

.memori-copy-menu-item-icon {
    width: 16px;
    height: 16px;
    color: var(--memori-text-color);
}

.memori-copy-menu-item-loading {
    display: flex;
    width: 16px;
    height: 16px;
    align-items: center;
    justify-content: center;
}

.memori-copy-menu-item-spinner {
    width: 12px;
    height: 12px;
    border: 2px solid color-mix(in oklch, var(--memori-border-color) 70%, transparent);
    border-radius: 50%;
    border-top: 2px solid var(--memori-primary);
    animation: memori-copy-spin 1s linear infinite;
}

.memori-copy-menu-item-text {
    min-width: 0;
    flex: 1;
}

.memori-copy-menu-item-label {
    margin-bottom: calc(var(--memori-spacing-xs) / 2);
    font-weight: var(--memori-text-weight-medium);
    line-height: 1.4;
}

.memori-copy-menu-item-description {
    color: var(--memori-copy-text-muted);
    font-size: 0.75rem;
    line-height: 1.3;
}

.memori-copy-menu-item-async-indicator {
    flex-shrink: 0;
}

.memori-copy-menu-item-async-badge {
    display: inline-block;
    padding: calc(var(--memori-spacing-xs) / 2) calc(var(--memori-spacing-xs) + 2px);
    border-radius: var(--memori-radius-xs);
    background: color-mix(in oklch, var(--memori-main-background) 78%, var(--memori-primary) 22%);
    color: var(--memori-text-color);
    font-size: 10px;
    font-weight: var(--memori-text-weight-semibold);
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

/* Toast Notifications */
.memori-copy-toast {
    position: fixed;
    z-index: calc(var(--memori-z-index-base, 0) + 1700);
    top: 20px;
    right: 20px;
    display: flex;
    max-width: 300px;
    align-items: center;
    padding: calc(var(--memori-spacing-sm) + var(--memori-spacing-xs)) var(--memori-spacing-md);
    border-radius: var(--memori-radius-surface);
    animation: memori-copy-toast-enter 0.3s ease-out;
    box-shadow: var(--memori-copy-shadow);
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    gap: var(--memori-spacing-sm);
}

@keyframes memori-copy-toast-enter {
    from {
        opacity: 0;
        transform: translateX(100%);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

.memori-copy-toast--success {
    border: 1px solid #22c55e;
    background: color-mix(in oklch, var(--memori-main-background) 82%, #22c55e 18%);
    color: var(--memori-text-color);
}

.memori-copy-toast--error {
    border: 1px solid #ef4444;
    background: color-mix(in oklch, var(--memori-main-background) 84%, #ef4444 16%);
    color: var(--memori-text-color);
}

.memori-copy-toast-icon {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
}

.memori-copy-toast-text {
    flex: 1;
    line-height: 1.4;
}

/* Responsive Design */
@media (max-width: 640px) {
    .memori-copy-toast {
        right: var(--memori-spacing-md);
        left: var(--memori-spacing-md);
        max-width: none;
    }

    .memori-copy-button,
    .memori-copy-button--dropdown {
        height: 38px;
        min-height: 38px;
        padding: 8px;
        font-size: 13px;
    }

    .memori-copy-menu-item {
        padding: calc(var(--memori-spacing-sm) + 2px) calc(var(--memori-spacing-sm) + var(--memori-spacing-xs));
    }
}

/* Print Media Queries */
@media print {
    .memori-copy-button-wrapper,
    .memori-copy-toast {
        display: none !important;
    }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
    .memori-copy-button {
        border-width: 2px;
    }

    .memori-copy-menu-item:hover:not(:disabled) {
        background: var(--memori-copy-surface-pressed);
        color: var(--memori-text-color);
    }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
    .memori-copy-button,
    .memori-copy-menu-item,
    .memori-copy-toast {
        transition: none;
    }

    .memori-copy-button-spinner,
    .memori-copy-menu-item-spinner {
        animation: none;
    }

    .memori-copy-toast {
        animation: none;
    }
}

