___CSS_LOADER_EXPORT___.push([module.id, `.memori-tab-switch {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    padding: var(--memori-spacing-xs, 4px);
    border: 1px solid color-mix(in srgb, var(--memori-text-color, #111827) 14%, transparent);
    border-radius: var(--memori-radius-control);
    background: color-mix(in srgb, var(--memori-text-color, #111827) 6%, transparent);
    gap: var(--memori-spacing-xs, 4px);
}

.memori-tab-switch__tab {
    display: inline-flex;
    min-height: 32px;
    align-items: center;
    justify-content: center;
    padding: 0.4rem 0.9rem;
    border: none;
    border-radius: calc(var(--memori-radius-control) - 2px);
    background: transparent;
    color: color-mix(in srgb, var(--memori-text-color, #111827) 72%, transparent);
    cursor: pointer;
    font-family: inherit;
    font-size: var(--memori-text-size-sm);
    font-weight: var(--memori-text-weight-medium);
    gap: var(--memori-spacing-xs, 0.375rem);
    line-height: 1.2;
    transition:
        background-color var(--memori-motion-duration-fast, 0.15s) var(--memori-motion-ease-out, ease),
        color var(--memori-motion-duration-fast, 0.15s) var(--memori-motion-ease-out, ease);
}

.memori-tab-switch__icon {
    width: 0.875rem;
    height: 0.875rem;
    flex-shrink: 0;
}

.memori-tab-switch__tab:hover {
    color: var(--memori-text-color, #111827);
}

.memori-tab-switch__tab[aria-pressed='true'],
.memori-tab-switch__tab--pressed {
    background: var(--memori-secondary-background, #fff);
    box-shadow: var(--memori-shadow-sm, 0 1px 2px rgba(0, 0, 0, 0.06));
    color: var(--memori-text-color, #111827);
    font-weight: var(--memori-text-weight-semibold);
}

.memori-tab-switch__tab:focus-visible {
    outline: 2px solid var(--memori-primary);
    outline-offset: 2px;
}

.memori-tab-switch__label {
    min-width: 0;
}
