___CSS_LOADER_EXPORT___.push([module.id, `.memori--powered-by {
    position: absolute;
    z-index: 1000;
    bottom: 1rem;
    left: 1rem;
    display: inline-flex;
    flex-wrap: nowrap;
    align-items: center;
    padding: 0.375rem 0.875rem 0.375rem 0.5rem;
    /* border: 1px solid var(--memori-border-color); */
    border-radius: 9999px;
    /* background-color: var(--memori-secondary-background); */
    color: color-mix(in srgb, var(--memori-text-color) 45%, transparent);
    font-size: 0.75rem;
    font-weight: 500;
    gap: 0.5rem;
    line-height: 1.2;
    white-space: nowrap;
}

.memori--powered-by-icon {
    width: 1.25rem;
    height: 1.25rem;
    flex-shrink: 0;
    opacity: 0.55;
}

.memori--powered-by-label {
    margin-top: 0;
    margin-bottom: 0;
    color: inherit;
}

.memori--powered-by-label a {
    color: inherit;
    text-decoration: underline;
    text-underline-offset: 2px;
}

.memori--powered-by-label a:hover,
.memori--powered-by-label a:focus-visible {
    color: var(--memori-primary, #744c99);
    text-decoration: underline;
}

@media (max-width: 870px) {
    .memori--powered-by {
        display: none !important;
    }
}
