___CSS_LOADER_EXPORT___.push([module.id, `.memori-chat--feedback button {
    padding: 0.5em;
    color: var(--memori-text-color);
    transition: all 0.3s ease-in-out;
}

.memori-chat--feedback button.memori-header--button {
    color: inherit;
}

.memori-chat--feedback button:hover,
.memori-chat--feedback button:focus {
    opacity: 1;
}

.memori-chat--feedback button .memori-button--icon svg.memori-chat--feedback-clicked {
    color: var(--memori-primary);
    fill: var(--memori-primary);
}

.memori-chat--feedback-menu {
    position: relative;
    display: inline-flex;
    text-align: left;
}

.memori-chat--feedback-tooltip-trigger {
    display: inline-flex;
}

.transition {
    transition-duration: 0.15s;
    transition-property: all;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

.ease-out {
    transition-timing-function: ease-out;
}

.ease-in {
    transition-timing-function: ease-in;
}

.duration-100 {
    transition-duration: 100ms;
}

.duration-200 {
    transition-duration: 200ms;
}

.opacity-0 {
    opacity: 0;
}

.opacity-100 {
    opacity: 1;
}

.scale-95 {
    transform: scale(0.95);
}

.scale-100 {
    transform: scale(1);
}

.memori-chat--feedback-menu-items {
    width: 14rem;
    border: 1px solid rgba(0, 0, 0, 0.05);
    border-radius: var(--memori-radius-surface);
    box-shadow:
        0 1px 3px 0 rgba(0, 0, 0, 0.1),
        0 1px 2px 0 rgba(0, 0, 0, 0.06);
    outline: none;
}

.memori-chat--feedback-menu-items:focus {
    outline: none;
}

.memori-chat--feedback-menu-items-container {
    padding: var(--memori-spacing-xs);
}

.memori-chat--feedback-menu-items button.memori-chat--feedback-menu-item {
    display: flex;
    width: 100%;
    align-items: center;
    padding: var(--memori-spacing-sm);
    border: none;
    border-radius: var(--memori-radius-control);
    margin: 0;
    background: none;
    box-shadow: none;
    color: var(--memori-text-color);
    cursor: pointer;
    font-family: inherit;
    font-size: var(--memori-text-size-sm);
    font-weight: inherit;
    line-height: inherit;
}

.memori-chat--feedback-menu-items button.memori-chat--feedback-menu-item:hover,
.memori-chat--feedback-menu-items button.memori-chat--feedback-menu-item:focus,
.memori-chat--feedback-menu-items button.memori-chat--feedback-menu-item:active,
.memori-chat--feedback-menu-items button.memori-chat--feedback-menu-item.memori-chat--feedback-menu-item-active {
    background-color: var(--memori-primary);
    color: var(--memori-primary-content);
}
