    /* Shared content axis for avatar + panel + status indicator (section 3).
       Overridable per-integration via the \`totemContentMaxWidth\` prop, which
       sets this custom property inline (e.g. wider for vertical kiosks). */
    --memori-totem-max-width: 600px;
    height: 100vh !important;
    height: 100dvh !important;
}

.memori-widget.memori-layout-totem .memori--global-background.no-background-image {
    background: linear-gradient(#333, #eee);
}

.memori-widget > .memori-spin.memori-totem-layout,
.memori-widget > .memori-widget__surface > .memori-spin.memori-totem-layout {
    position: relative;
    display: flex;
    height: 100%;
    flex-direction: column;
}

/* Rail/header is an overlay so it does not consume vertical flow: the 3D
   scene height equals 100vh minus the panel height, per spec. */
.memori-totem-layout--header {
    position: absolute;
    z-index: 101;
    top: var(--memori-spacing-md);
    right: var(--memori-spacing-md);
    text-align: right;
}

/* Avatar fills the flex space above the panel: height = 100vh - panel. */
.memori-totem-layout--avatar {
    position: relative;
    min-height: 0;
    flex: 1 1 auto;
}

/* Avatar shares the same centered axis and max-width as the panel below it,
   so on wide desktop the face is not lost in empty space (section 3). */
.memori-totem-layout--avatar .memori--avatar-wrapper {
    position: absolute;
    z-index: 0;
    top: 0;
    bottom: 0;
    left: 50%;
    overflow: hidden;
    width: 100%;
    max-width: var(--memori-totem-max-width, 600px);
    height: 100%;
    transform: translateX(-50%);
}

.memori-totem-layout--avatar .memori--blob-container {
    display: block;
}

@media (max-width: 480px) {
    .memori-totem-layout--avatar .memori--blob-container {
        display: block;
    }
}

@media (max-width: 870px) {
    .memori-totem-layout--avatar .memori--blob-container {
        display: block;
    }
}

/* ==========================================================================
   SECTION 4–5 — Side rail: one visible container, two tiers, flat surface.
   Solid surface (no blur) so text/icon contrast never depends on the 3D
   frame behind it.
   ========================================================================== */
.memori-totem-rail {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    padding: var(--memori-spacing-xs);
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-control);
    background: var(--memori-secondary-background);
    gap: var(--memori-spacing-xs);
}

.memori-totem-rail--group {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--memori-spacing-xs);
}

.memori-totem-rail--divider {
    width: 24px;
    height: 1px;
    flex-shrink: 0;
    background: var(--memori-border-color);
}

.memori-totem-rail--button,
.memori-totem-rail--button button {
    width: 40px;
    height: 40px;
    border-radius: var(--memori-radius-xs);
    aspect-ratio: 1;
}

.memori-totem-rail--menu-content {
    display: flex;
    min-width: 220px;
    flex-direction: column;
    gap: 2px;
}

.memori-totem-rail--menu-identity {
    display: flex;
    flex-direction: column;
    padding: var(--memori-spacing-sm) var(--memori-spacing-sm) var(--memori-spacing-xs);
    border-bottom: 1px solid var(--memori-border-color);
    margin-bottom: var(--memori-spacing-xs);
    gap: 2px;
}

.memori-totem-rail--menu-identity-name {
    color: var(--memori-text-color);
    font-weight: var(--memori-text-weight-bold);
}

.memori-totem-rail--menu-identity-email {
    color: color-mix(in srgb, var(--memori-text-color) 70%, transparent);
    font-size: 0.8rem;
}

.memori-totem-rail--menu-item,
.memori-totem-rail--menu-item button {
    width: 100%;
    justify-content: flex-start;
}

.memori-totem-layout .memori-chat--cover {
    display: none;
}

.memori-totem-layout .memori--cover {
    padding: 0;
    background: none;
}

.memori-widget.memori-layout-totem .memori-totem-layout > .memori--powered-by {
    top: auto;
    right: auto;
    bottom: 1rem;
    left: 1rem;
}

