/* Panel sits below the avatar and never grows into it: capped height with
   internal scroll instead of pushing the scene up. */
.memori-totem-layout--controls {
    z-index: 100;
    display: flex;
    width: 100%;
    min-height: 0;
    max-height: 48vh;
    flex-direction: column;
    flex-shrink: 0;
}

/* ==========================================================================
   SECTION 2–3 — Single unified panel + shared alignment axis
   One container (surface + 1px border + 12px radius). Inner sections have
   NO border/shadow/width of their own, only 1px dividers between them.
   A definite height (not just max-height) is required so nested overflow-y
   auto actually scrolls instead of clipping.
   ========================================================================== */
.memori-totem-layout--controls .memori-chat--wrapper,
.memori-totem-layout--controls .memori--start-panel {
    display: flex;
    overflow: hidden;
    width: 100%;
    max-width: var(--memori-totem-max-width, 600px);
    height: 48vh;
    min-height: 0;
    max-height: 48vh;
    box-sizing: border-box;
    flex: 1 1 auto;
    flex-direction: column;
    padding: 0;
    border: 1px solid var(--memori-border-color);
    border-radius: var(--memori-radius-surface);
    margin: 0 auto;
    background: var(--memori-secondary-background);
}

/* Nested conversation column must not add its own axis/padding/surface. */
.memori-totem-layout--controls .memori-conversation-column {
    display: flex;
    overflow: hidden;
    width: 100%;
    max-width: none;
    height: auto;
    min-height: 0;
    flex: 1 1 0%;
    flex-direction: column;
    padding: 0;
    margin: 0;
}

/* Messages section: remaining panel height; children must not size to content. */
.memori-totem-layout--controls .memori-chat--history,
.memori-totem-layout--controls .memori-chat--history.memori-chat--history-touch {
    display: flex;
    overflow: hidden;
    height: auto !important;
    min-height: 0;
    flex: 1 1 0%;
    flex-direction: column;
    border: none;
    border-radius: 0;
    margin: 0;
    background: transparent;
}

.memori-totem-layout--controls .memori-chat--content,
.memori-totem-layout--controls .memori-chat--content.memori-chat--content-touch {
    height: 0;
    min-height: 0;
    max-height: none;
    flex: 1 1 auto;
    padding: var(--memori-spacing-md);
    background: transparent;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.memori-totem-layout--controls .memori-chat--content > * {
    flex-shrink: 0;
}

/* Input section: 1px divider above, no own surface. */
.memori-totem-layout--controls .memori-chat-inputs-wrapper {
    flex-shrink: 0;
    padding: var(--memori-spacing-md);
    border-top: 1px solid var(--memori-border-color);
    background: transparent;
}

.memori-totem-layout--controls .memori-chat-inputs--container {
    border-width: 1px;
    border-radius: var(--memori-radius-control);
}

.memori-totem-layout--controls .memori-chat--bubble,
.memori-totem-layout--controls .memori-chat--bubble.memori-chat--user-bubble {
    font-size: 1.125rem;
}

/* Start-panel body scrolls internally instead of stretching the panel. */
.memori-totem-layout--controls .memori--start-panel__body {
    min-height: 0;
    flex: 1 1 0%;
    padding-bottom: var(--memori-spacing-lg);
    overflow-y: auto;
}

.memori-totem-layout--controls .memori--start-actions {
    position: sticky;
    z-index: 1;
    bottom: 0;
    padding-bottom: var(--memori-spacing-sm);
    background: var(--memori-secondary-background);
}

@media (max-width: 870px) {
    .memori-totem-layout--controls .memori-chat--wrapper,
    .memori-totem-layout--controls .memori--start-panel {
        max-width: 100%;
    }
}

@media (max-width: 480px) {
    .memori-totem-layout .memori-send-on-enter-menu {
        display: none;
    }

    .memori-totem-layout .memori-header--button-settings {
        display: none;
    }
}

.memori-totem-layout .memori--avatar-toggle {
    display: none;
    width: 100%;
    justify-content: center;
}

.memori-totem-layout .memori--title,
.memori-totem-layout .memori--description,
.memori-totem-layout .memori--needsPosition {
    color: var(--memori-text-color);
}

.memori-totem-layout .memori--global-background-image {
    background-image: linear-gradient(rgba(0, 0, 0, 0.8), rgba(200, 200, 200, 0.8));
}

@media (min-width: 481px) {
    .memori-widget.memori-controls-center .memori-totem-layout--controls {
        position: absolute;
        top: 40%;
        width: 100%;
    }
}

.memori-widget.memori-layout-totem.memori--hide-emissions
    .memori-totem-layout--controls
    .memori-chat--bubble-container:not(.memori-chat--bubble-from-user),
.memori-widget.memori-layout-totem.memori--hide-emissions.memori--with-speechkey
    .memori-totem-layout--controls
    .memori-chat--bubble-container:not(.memori-chat--bubble-from-user) {
    display: none;
}

.memori-totem-layout--avatar .memori-blob {
    z-index: 2;
}

.memori-totem-layout--avatar .memori--avatar-wrapper > div canvas + div {
    position: absolute !important;
    width: 100%;
    height: 100%;
    transform: none !important;
}

.memori-totem-layout--avatar .memori--avatar-wrapper .avatar-loader {
    display: flex;
    width: 100%;
    height: 100%;
    align-items: center;
    justify-content: center;
    transform: none !important;
}

.memori-totem-layout--avatar .memori--avatar-wrapper .avatar-loader figure {
    text-align: center;
}

.memori-totem-layout--avatar .memori--avatar-wrapper .avatar-loader .memori-spin--spinner {
    background: none;
}
